const escapeHtml = (value='') => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatDate = value => value ? new Date(value).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'}) : '—';
const statusLabel = value => ({pending:'Not submitted',submitted:'For review',verified:'Completed',rejected:'Needs revision'})[value] || value;
const initials = name => {const parts=String(name||'').trim().split(/\s+/).filter(Boolean);while(parts.length>1&&/^(jr\.?|sr\.?|ii|iii|iv)$/i.test(parts.at(-1)))parts.pop();return `${parts[0]?.[0]||'R'}${parts.length>1?parts.at(-1)[0]:''}`.toUpperCase()};
function showToast(message, type='success'){const toast=document.querySelector('#toast');toast.textContent=message;toast.className=`toast show ${type}`;setTimeout(()=>toast.className='toast',2800)}

async function api(path, options={}, allowRefresh=true) {
  const response = await fetch('/api'+path,{...options,headers:{'content-type':'application/json'}});
  const result = await response.json().catch(()=>({error:'The server returned an invalid response.'}));
  if(response.status===401&&allowRefresh&&!['/login','/refresh','/invitations/session'].includes(path)){
    const refreshed=await api('/refresh',{method:'POST'},false).catch(()=>null);
    if(refreshed)return api(path,options,false);
  }
  if(!response.ok){if(response.status===401&&path!=='/login')signOut(false);throw new Error(result.error||'The request could not be completed.');}
  if(options.method&&!['GET','HEAD'].includes(options.method.toUpperCase())&&state.user&&!['/refresh','/login','/logout'].includes(path))window.publishLiveChange?.();
  return result;
}

function openModal(content, wide=false){const layer=document.createElement('div');layer.className='modal-layer';layer.id='modal';layer.innerHTML=`<section class="dialog ${wide?'dialog-wide':''}" role="dialog" aria-modal="true">${content}</section>`;layer.onclick=e=>{if(e.target===layer)closeModal()};document.body.appendChild(layer);document.addEventListener('keydown',closeOnEscape);return layer;}
function closeOnEscape(e){if(e.key==='Escape')closeModal()}
function closeModal(){if(document.querySelector('#profile-crop-layer'))closeProfileCrop();document.querySelector('#modal')?.remove();document.removeEventListener('keydown',closeOnEscape);window.flushLiveRender?.()}
const dialogHeader = (eyebrow,title) => `<div class="dialog-head"><div><span class="kicker">${escapeHtml(eyebrow)}</span><h2>${escapeHtml(title)}</h2></div><button class="icon-btn" onclick="closeModal()" aria-label="Close">×</button></div>`;

function authBrand(registration=false){const title=registration?'Begin your journey.<br><em>Join your class.</em>':'Learn with purpose.<br><em>Live the legacy.</em>',description=registration?'Create your RizLife student account with your official APC details and the permanent class code from your teacher.':"Explore José Rizal's life, complete meaningful course quests, submit evidence, and follow every milestone in one focused academic workspace.";return `<section class="auth-brand"><div class="auth-brand-inner"><div class="auth-institution"><img src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div><b>Asia Pacific College</b><span>Learning Management Portal</span></div></div><div class="auth-story"><span class="auth-label">RizLife Academic Workspace</span><h1>${title}</h1><p>${description}</p><div class="auth-course"><span>COURSE WORKSPACE</span><b>Life and Works of Rizal</b></div><div class="auth-trust"><span>${icons.check} APC institutional access</span><span>${icons.check} Teacher-approved enrollment</span></div></div></div><div class="auth-rizal-visual" aria-hidden="true"><span></span><img src="assets/rizal-assistant.png" alt=""></div><div class="auth-watermark">RIZLIFE</div></section>`}
function mobileAuthBrand(){return `<div class="mobile-brand"><img src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div><b>Asia Pacific College</b><span>RizLife Academic Workspace</span></div></div>`}
function loginPage(){app.innerHTML=`<main class="auth-layout">${authBrand()}<section class="auth-form-wrap"><form class="auth-card" onsubmit="signIn(event)">${mobileAuthBrand()}<span class="auth-label dark">RizLife Academic Workspace</span><h2>Welcome back.</h2><p class="form-intro">Sign in with your assigned APC student or faculty account to continue your Rizal learning journey.</p><label class="form-field"><span>Email address</span><input id="login-email" type="email" autocomplete="username" placeholder="name@apc.edu.ph" required autofocus></label><label class="form-field"><span>Password</span><span class="password-field"><input id="login-password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" onclick="togglePassword('login-password',this)">Show</button></span></label><p class="form-error" id="login-error" role="alert"></p><button class="button primary full" id="login-button">Enter RizLife Workspace</button><div class="auth-divider"><span>New student?</span></div><button type="button" class="button secondary full" onclick="registrationPage()">Create student account</button><p class="auth-help">Having trouble signing in? Contact your course administrator.</p></form></section></main>`}
function togglePassword(id,button){const input=document.getElementById(id),showing=input.type==='text';input.type=showing?'password':'text';button.textContent=showing?'Show':'Hide'}
function registrationPage(){app.innerHTML=`<main class="auth-layout registration-layout">${authBrand(true)}<section class="auth-form-wrap registration-wrap"><form class="auth-card registration-card" onsubmit="registerStudent(event)">${mobileAuthBrand()}<span class="auth-label dark">Student registration</span><h2>Create your account.</h2><p class="form-intro">Use the same details shown on your official APC student record. Your teacher will review them before access is activated.</p><div class="registration-name-grid"><label class="form-field"><span>First name</span><input id="register-first-name" maxlength="50" autocomplete="given-name" placeholder="Juan" required autofocus></label><label class="form-field middle-initial-field"><span>Middle initial <small>Optional</small></span><input id="register-middle-initial" maxlength="1" autocomplete="additional-name" inputmode="text" placeholder="M"></label><label class="form-field"><span>Last name</span><input id="register-last-name" maxlength="50" autocomplete="family-name" placeholder="Dela Cruz" required></label></div><div class="registration-details-grid"><label class="form-field"><span>APC student email</span><input id="register-email" type="email" autocomplete="email" placeholder="name@student.apc.edu.ph" required></label><label class="form-field"><span>Student ID</span><input id="register-student-number" maxlength="100" autocomplete="off" placeholder="2026-00000" required></label></div><label class="form-field"><span>Class join code</span><input id="register-code" maxlength="20" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="RZ-ABC123-DEF456" required><small>Enter the permanent code provided by your teacher.</small></label><div class="registration-details-grid"><label class="form-field"><span>Password</span><span class="password-field"><input id="register-password" type="password" minlength="10" autocomplete="new-password" placeholder="Create a password" required><button type="button" onclick="togglePassword('register-password',this)">Show</button></span><small>10+ characters with uppercase, lowercase, and a number.</small></label><label class="form-field"><span>Confirm password</span><span class="password-field"><input id="register-confirm" type="password" minlength="10" autocomplete="new-password" placeholder="Repeat password" required><button type="button" onclick="togglePassword('register-confirm',this)">Show</button></span></label></div><div class="invite-notice registration-notice"><b>Teacher approval required</b><span>Your account will remain pending until your teacher confirms your name, APC email, Student ID, and class.</span></div><p class="form-error" id="register-error" role="alert"></p><button class="button primary full">Submit for teacher approval</button><button type="button" class="text-button full registration-return" onclick="loginPage()">Already have an account? Return to sign in</button></form></section></main>`}
function registrationPendingPage(sectionName){app.innerHTML=`<main class="auth-layout registration-layout">${authBrand(true)}<section class="auth-form-wrap"><div class="auth-card registration-success-card"><div class="registration-success-icon">${icons.clock}</div><span class="auth-label dark">Registration submitted</span><h2>Waiting for teacher approval.</h2><p class="form-intro">Your request to join <b>${escapeHtml(sectionName)}</b> was sent successfully.</p><div class="registration-next-steps"><span><b>1</b>Your teacher checks your official APC details.</span><span><b>2</b>Once approved, return here and sign in with your APC email and password.</span></div><button class="button primary full" onclick="loginPage()">Return to sign in</button></div></section></main>`}
async function registerStudent(event){event.preventDefault();const password=document.querySelector('#register-password').value,confirmPassword=document.querySelector('#register-confirm').value,error=document.querySelector('#register-error'),button=event.submitter,middleInitial=document.querySelector('#register-middle-initial').value.trim();if(middleInitial&&!/^\p{L}$/u.test(middleInitial)){error.textContent='Middle initial must be one letter.';return}if(password!==confirmPassword){error.textContent='The passwords do not match.';return}button.disabled=true;button.textContent='Submitting for approval';error.textContent='';try{const result=await api('/register',{method:'POST',body:JSON.stringify({firstName:document.querySelector('#register-first-name').value,middleInitial,lastName:document.querySelector('#register-last-name').value,email:document.querySelector('#register-email').value,studentNumber:document.querySelector('#register-student-number').value,code:document.querySelector('#register-code').value,password})},false);registrationPendingPage(result.sectionName)}catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Submit for teacher approval'}}

function trustedInvitationUrl(value){try{const url=new URL(value);return url.protocol==='https:'&&url.hostname.endsWith('.supabase.co')&&url.pathname==='/auth/v1/verify'?url.toString():null}catch{return null}}
function invitationLandingPage(value){const invitationUrl=trustedInvitationUrl(value);if(!invitationUrl)return errorScreen('This invitation link is not valid. Ask your teacher to send a new invitation.');app.innerHTML=`<main class="invite-layout"><section class="invite-card"><div class="invite-emblem">R</div><span class="kicker">Rizal Life invitation</span><h1>Join your class</h1><p>Your teacher invited you to the Rizal Life learning workspace. Continue to verify your email and activate your student account.</p><div class="invite-notice">Use the same browser until your account setup is complete.</div><a class="button primary full invite-button" href="${escapeHtml(invitationUrl)}">Accept invitation</a><a class="invite-return" href="/">Return to sign in</a></section></main>`}
async function acceptInvitation(params){app.innerHTML=loadingScreen();try{const result=await api('/invitations/session',{method:'POST',body:JSON.stringify({accessToken:params.get('access_token'),refreshToken:params.get('refresh_token')})},false);state.user=result.user;history.replaceState(null,'',location.pathname);invitationPasswordPage()}catch(e){history.replaceState(null,'',location.pathname);errorScreen(e.message)}}
function invitationPasswordPage(){const sections=state.user.sectionNames?.length?` You will join ${state.user.sectionNames.map(escapeHtml).join(', ')}.`:'';app.innerHTML=`<main class="invite-layout"><form class="invite-card" onsubmit="finishInvitation(event)"><div class="invite-emblem">R</div><span class="kicker">Account setup</span><h1>Welcome, ${escapeHtml(state.user.name.split(' ')[0])}</h1><p>Create your password to activate your student account.${sections}</p><label class="form-field"><span>New password</span><input id="invite-password" type="password" minlength="10" autocomplete="new-password" required><small>Use at least 10 characters with uppercase, lowercase, and a number.</small></label><label class="form-field"><span>Confirm password</span><input id="invite-password-confirm" type="password" minlength="10" autocomplete="new-password" required></label><p class="form-error" id="invite-error" role="alert"></p><button class="button primary full" id="invite-submit">Activate account</button></form></main>`}
async function finishInvitation(event){event.preventDefault();const password=document.querySelector('#invite-password').value,confirmPassword=document.querySelector('#invite-password-confirm').value,error=document.querySelector('#invite-error'),button=document.querySelector('#invite-submit');if(password!==confirmPassword){error.textContent='The passwords do not match.';return}button.disabled=true;button.innerHTML='<span class="button-spinner"></span>Activating account';error.textContent='';try{await api('/invitations/password',{method:'POST',body:JSON.stringify({password})});showToast('Your student account is ready.');history.replaceState(null,'','/#overview');await loadData()}catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Activate account'}}

async function signIn(event){event.preventDefault();const button=document.querySelector('#login-button'),error=document.querySelector('#login-error');button.disabled=true;button.innerHTML='<span class="button-spinner"></span>Signing in';error.textContent='';try{const result=await api('/login',{method:'POST',body:JSON.stringify({email:document.querySelector('#login-email').value,password:document.querySelector('#login-password').value})});state.user=result.user;location.hash='overview';await loadData();}catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Sign in';}}
async function signOut(callServer=true){if(callServer){await api('/logout',{method:'POST'}).catch(()=>{});window.publishLiveChange?.('logout')}state.user=null;state.assistantMessages=[];state.assistantOpen=false;history.replaceState(null,'',location.pathname);loginPage();}
function confirmLogout(){closeProfileMenu();closeModal();openModal(`${dialogHeader('Account','Log out')}<p class="dialog-description">Are you sure you want to log out?</p><div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button type="button" class="button danger" onclick="performLogout(this)">Log Out</button></div>`)}
async function performLogout(button){button.disabled=true;button.textContent='Logging out…';await signOut(true)}

function navigation(){const teacher=state.user.role==='teacher';return teacher?[['overview','Overview','home'],['tasks','Tasks','tasks'],['reviews','Reviews','review'],['class','Classes','people']]:[['overview','My journey','home'],['quests','Quests','tasks'],['submissions','Submissions','submit'],['class','My classes','people']];}
function avatarContent(user=state.user){return user?.avatarUrl?`<img src="${escapeHtml(user.avatarUrl)}" alt="">`:`<span aria-hidden="true">${initials(user?.name||'R')}</span>`}
function avatarMarkup(user=state.user,size='default',label=''){return `<span class="avatar avatar-${size}" ${label?`role="img" aria-label="${escapeHtml(label)}"`:'aria-hidden="true"'}>${avatarContent(user)}</span>`}
function reconcileView(current,next){
  if(current.isEqualNode(next))return;
  if(current.nodeType!==next.nodeType||(current.nodeType===1&&current.tagName!==next.tagName)){
    current.replaceWith(next.cloneNode(true));return;
  }
  if(current.nodeType===3){current.textContent=next.textContent;return}
  if(current.nodeType!==1)return;
  for(const attribute of [...current.attributes])if(!next.hasAttribute(attribute.name))current.removeAttribute(attribute.name);
  for(const attribute of [...next.attributes])if(current.getAttribute(attribute.name)!==attribute.value)current.setAttribute(attribute.name,attribute.value);
  if(current instanceof HTMLInputElement&&current!==document.activeElement&&current.value!==next.value)current.value=next.value;
  const oldChildren=[...current.childNodes],newChildren=[...next.childNodes];
  for(let index=0;index<Math.max(oldChildren.length,newChildren.length);index++){
    if(!newChildren[index])oldChildren[index].remove();
    else if(!oldChildren[index])current.appendChild(newChildren[index].cloneNode(true));
    else reconcileView(oldChildren[index],newChildren[index]);
  }
}
function patchShell(content){
  const existing=app.querySelector(':scope > .app-shell');
  if(!existing||existing.classList.contains('student-shell')!==(state.user.role==='student'))return false;
  const main=existing.querySelector('main.content');
  const next=document.createElement('main');
  next.className='content';
  next.innerHTML=content;
  reconcileView(main,next);
  for(const link of existing.querySelectorAll('nav a[href^="#"]')){
    const active=link.getAttribute('href')===`#${state.page}`;
    link.classList.toggle('active',active);
    if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');
    if(link.closest('.sidebar')&&link.getAttribute('href')==='#reviews'){
      const count=state.teacher?.queue?.length||0;
      link.querySelector('em')?.remove();
      if(count){const badge=document.createElement('em');badge.textContent=count;link.appendChild(badge)}
    }
  }
  const profile=existing.querySelector('.sidebar-profile-trigger');
  if(profile){profile.setAttribute('aria-label',`Open profile menu for ${state.user.name}`);profile.querySelector('.avatar').innerHTML=avatarContent(state.user);profile.querySelector('b').textContent=state.user.name}
  const headerAvatar=existing.querySelector('.profile-avatar-button .avatar');
  if(headerAvatar)headerAvatar.innerHTML=avatarContent(state.user);
  const menu=document.querySelector('#profile-dropdown .profile-dropdown-head');
  if(menu){menu.querySelector('.avatar').innerHTML=avatarContent(state.user);menu.querySelector('b').textContent=state.user.name;menu.querySelector('small').textContent=state.user.email}
  return true;
}
function shell(content){
  if(patchShell(content))return;
  const nav=navigation(),student=state.user.role==='student',collapsed=state.sidebarCollapsed?'sidebar-collapsed':'',roleLabel=student?'Student account':'Faculty account';
  const profileTrigger=`<button class="sidebar-user sidebar-profile-trigger" onclick="toggleProfileMenu(this,event)" onkeydown="profileTriggerKeydown(event,this)" aria-label="Open profile menu for ${escapeHtml(state.user.name)}" aria-haspopup="menu" aria-expanded="false">${avatarMarkup(state.user,'sidebar')}<span class="sidebar-user-copy"><b>${escapeHtml(state.user.name)}</b><span>${roleLabel}</span></span></button>`;
  app.innerHTML=`<div class="app-shell ${student?'student-shell':'teacher-shell'} ${collapsed}"><button class="sidebar-scrim" onclick="closeMobileNav()" aria-label="Close navigation"></button><aside class="sidebar" id="workspace-sidebar"><div class="sidebar-brand"><img class="apc-logo" src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div class="sidebar-brand-copy"><b>Asia Pacific College</b><span>RizLife Workspace</span></div><button class="sidebar-collapse-button" onclick="toggleSidebar()" aria-label="${state.sidebarCollapsed?'Expand':'Collapse'} sidebar" aria-expanded="${!state.sidebarCollapsed}" aria-controls="workspace-sidebar">${icons.menu}</button></div><div class="nav-context"><span>Workspace</span><b>${student?'Student Portal':'Faculty Portal'}</b></div><nav aria-label="${student?'Student':'Teacher'} workspace">${nav.map(([id,label,icon])=>`<a href="#${id}" class="nav-link ${state.page===id?'active':''}" title="${escapeHtml(label)}" ${state.page===id?'aria-current="page"':''} onclick="prepareNavigation('${id}')">${icons[icon]}<span>${label}</span>${id==='reviews'&&state.teacher?.queue?.length?`<em>${state.teacher.queue.length}</em>`:''}</a>`).join('')}</nav><div class="sidebar-course"><span>COURSE WORKSPACE</span><b>RizLife</b><small>Life and Works of Rizal</small></div>${profileTrigger}</aside><div class="main-column"><header class="workspace-header"><button class="icon-btn workspace-menu" onclick="toggleSidebar()" aria-label="Open navigation" aria-expanded="false" aria-controls="workspace-sidebar">${icons.menu}</button><div class="mobile-logo"><img class="apc-logo" src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div><b>Asia Pacific College</b><span>RizLife · ${student?'Student':'Faculty'} Portal</span></div></div><button class="profile-avatar-button" onclick="toggleProfileMenu(this,event)" onkeydown="profileTriggerKeydown(event,this)" aria-label="Open profile menu" aria-haspopup="menu" aria-expanded="false">${avatarMarkup(state.user,'header')}</button></header><main class="content">${content}</main>${assistantWidget(student)}${student?`<nav class="student-bottom-nav" aria-label="Student navigation">${nav.map(([id,label,icon])=>`<a href="#${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''} onclick="prepareNavigation('${id}')">${icons[icon]}<span>${label}</span></a>`).join('')}</nav>`:''}</div></div>`;
}
function closeProfileMenu({restoreFocus=false}={}){const trigger=document.querySelector('[aria-haspopup="menu"][aria-expanded="true"]');document.querySelector('#profile-dropdown')?.remove();trigger?.setAttribute('aria-expanded','false');document.removeEventListener('click',closeProfileMenu);document.removeEventListener('keydown',profileMenuKeydown);if(restoreFocus)trigger?.focus()}
function profileTriggerKeydown(event,button){if(['ArrowDown','Enter',' '].includes(event.key)){event.preventDefault();if(!document.querySelector('#profile-dropdown'))toggleProfileMenu(button,event);queueMicrotask(()=>document.querySelector('#profile-dropdown [role="menuitem"]')?.focus())}}
function profileMenuKeydown(event){const menu=document.querySelector('#profile-dropdown');if(!menu)return;if(event.key==='Escape'){event.preventDefault();closeProfileMenu({restoreFocus:true});return}const items=[...menu.querySelectorAll('[role="menuitem"]')],index=items.indexOf(document.activeElement);if(event.key==='ArrowDown'){event.preventDefault();items[(index+1+items.length)%items.length]?.focus()}if(event.key==='ArrowUp'){event.preventDefault();items[(index-1+items.length)%items.length]?.focus()}if(event.key==='Home'){event.preventDefault();items[0]?.focus()}if(event.key==='End'){event.preventDefault();items.at(-1)?.focus()}}
function toggleProfileMenu(button,event){event?.stopPropagation();if(document.querySelector('#profile-dropdown')){closeProfileMenu();return}const menu=document.createElement('div'),rect=button.getBoundingClientRect();menu.id='profile-dropdown';menu.className='profile-dropdown';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Account menu');menu.innerHTML=`<div class="profile-dropdown-head">${avatarMarkup(state.user,'dropdown')}<div><b>${escapeHtml(state.user.name)}</b><small>${escapeHtml(state.user.email)}</small></div></div><button role="menuitem" tabindex="-1" onclick="openProfile('view')">View Profile</button><button role="menuitem" tabindex="-1" onclick="openProfile('edit')">Edit Profile</button><button role="menuitem" tabindex="-1" class="logout-menu-item" onclick="confirmLogout()">${icons.logout}Log Out</button>`;document.body.appendChild(menu);const width=Math.min(300,innerWidth-24),left=Math.max(12,Math.min(rect.left,innerWidth-width-12)),height=menu.offsetHeight,top=rect.top>height+16?rect.top-height-8:Math.min(innerHeight-height-12,rect.bottom+8);menu.style.cssText=`width:${width}px;left:${left}px;top:${Math.max(12,top)}px`;button.setAttribute('aria-expanded','true');setTimeout(()=>document.addEventListener('click',closeProfileMenu),0);document.addEventListener('keydown',profileMenuKeydown)}
function toggleSidebar(){const shell=document.querySelector('.app-shell'),sidebar=document.querySelector('.sidebar');if(!shell||!sidebar)return;if(matchMedia('(max-width: 900px)').matches){if(shell.classList.contains('student-shell'))return;sidebar.classList.toggle('open');shell.classList.toggle('drawer-open',sidebar.classList.contains('open'));document.querySelector('.workspace-menu')?.setAttribute('aria-expanded',String(sidebar.classList.contains('open')));return}shell.classList.toggle('sidebar-collapsed');state.sidebarCollapsed=shell.classList.contains('sidebar-collapsed');localStorage.setItem('rizlife-sidebar',state.sidebarCollapsed?'collapsed':'expanded');document.querySelector('.sidebar-collapse-button')?.setAttribute('aria-expanded',String(!state.sidebarCollapsed));document.querySelector('.sidebar-collapse-button')?.setAttribute('aria-label',`${state.sidebarCollapsed?'Expand':'Collapse'} sidebar`)}
function closeMobileNav(){document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.app-shell')?.classList.remove('drawer-open');document.querySelector('.workspace-menu')?.setAttribute('aria-expanded','false')}
function prepareNavigation(page){const reopenQuestList=page==='quests'&&state.page==='quests'&&state.selectedQuestId;if(page==='quests')state.selectedQuestId=null;closeMobileNav();if(reopenQuestList)queueMicrotask(()=>studentQuests(state.student.quests))}
function toggleMobileNav(){toggleSidebar()}
function pageHeader(title,description,action=''){return `<header class="page-header"><div><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p></div>${action}</header>`}
function metric(label,value,note,tone=''){return `<article class="metric ${tone}"><span>${escapeHtml(label)}</span><strong>${value}</strong><small>${escapeHtml(note)}</small></article>`}
function statusPill(status){return `<span class="status-pill ${status}"><i></i>${statusLabel(status)}</span>`}
function emptyState(title,message){return `<div class="empty-state"><div class="empty-icon">${icons.tasks}</div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(message)}</p></div>`}
function counts(quests){const result={verified:0,submitted:0,rejected:0,pending:0};quests.forEach(q=>result[q.submission?.status||'pending']++);return result}

function loadingScreen(){return `<div class="loading-shell" aria-label="Loading workspace"><aside><span class="skeleton brand-skeleton"></span>${[1,2,3,4].map(()=>'<span class="skeleton nav-skeleton"></span>').join('')}</aside><main><span class="skeleton title-skeleton"></span><div class="skeleton-grid">${[1,2,3,4].map(()=>'<span class="skeleton metric-skeleton"></span>').join('')}</div><span class="skeleton content-skeleton"></span></main></div>`}
function contentSkeleton(label='Loading content'){return `<section class="content-loading" aria-label="${escapeHtml(label)}"><span class="skeleton title-skeleton"></span><div class="skeleton-grid">${[1,2,3,4].map(()=>'<span class="skeleton metric-skeleton"></span>').join('')}</div><span class="skeleton content-skeleton"></span></section>`}
function modalSkeleton(){return `<div class="modal-skeleton" aria-label="Loading details"><span class="skeleton modal-title-skeleton"></span><span class="skeleton modal-line-skeleton"></span><span class="skeleton modal-block-skeleton"></span>${[1,2,3].map(()=>'<span class="skeleton modal-line-skeleton"></span>').join('')}</div>`}
function errorScreen(message){app.innerHTML=`<main class="system-state"><div class="brand-mark brand-mark-large">R</div><p class="kicker">Rizal Life</p><h1>We couldn't load your workspace</h1><p>${escapeHtml(message)}</p><button class="button primary" onclick="loadData()">Try again</button><button class="text-button" onclick="signOut()">Return to sign in</button></main>`}
async function loadData(){if(!app.querySelector('.app-shell'))app.innerHTML=loadingScreen();try{if(!state.user)state.user=(await api('/me')).user;if(state.user.role==='student'){[state.student,state.studentClasses]=await Promise.all([api('/student/card'),api('/student/classes')])}else{state.sections=(await api('/teacher/sections')).sections;if(state.sectionId!=='all'&&!state.sections.some(s=>Number(s.id)===Number(state.sectionId)))state.sectionId=state.sections.length>1?'all':state.sections[0]?.id||null;if(state.sectionId){localStorage.setItem('rizlife-section',state.sectionId);state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`)}else state.teacher={students:[],queue:[],recent:[],taskCount:0,section:null,sections:[]}}route();}catch(e){if(state.user)errorScreen(e.message);else loginPage();showToast(e.message,'error')}}
function route(){const allowed=navigation().map(x=>x[0]),requested=location.hash.slice(1);state.page=allowed.includes(requested)?requested:'overview';if(state.user.role==='student')renderStudent();else{renderTeacher();queueMicrotask(enhanceTeacherPage)}}
window.addEventListener('hashchange',()=>state.user&&route());
const compactNavigationQuery=matchMedia('(max-width: 900px)');
compactNavigationQuery.addEventListener?.('change',closeMobileNav);

function renderStudent(){const q=state.student.quests;if(state.page==='overview')return studentOverview(q);if(state.page==='quests')return state.selectedQuestId?studentQuestDetail(state.selectedQuestId):studentQuests(q);if(state.page==='class')return myClassesPage();studentSubmissions(q)}
function joinClassForm(){return `<section class="scholar-panel join-code-panel"><div class="class-panel-heading"><div><span class="journey-eyebrow">Class invitation</span><h2>Join another class</h2><p>Each class has one permanent join code managed by its teacher.</p></div></div><form onsubmit="redeemJoinCode(event)"><label class="form-field"><span>Class invitation code</span><span class="join-code-form-row"><input id="student-join-code" maxlength="20" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="RZ-ABC123-DEF456" aria-describedby="join-code-help join-code-error" required><button class="button primary">Join class</button></span><small id="join-code-help">Ask your teacher for the class join code.</small></label><p class="form-error" id="join-code-error" role="alert"></p></form></section>`}
function myClassesPage(){
  const classes=state.studentClasses?.classes||[];
  const cards=classes.map(classroom=>{
    const progress=classroom.myProgress;
    const preview=previewClassmates(classroom);
    return `<section class="scholar-panel my-class-card"><div class="my-class-heading"><div><h2>${escapeHtml(classroom.name)}</h2><p class="my-class-teacher"><span>Teacher</span> ${escapeHtml(classroom.teacherName)}</p><p>${classroom.classmateCount} student${classroom.classmateCount===1?'':'s'} · ${classroom.questCount} active quest${classroom.questCount===1?'':'s'}</p></div><div class="my-class-progress" aria-label="${progress.verified} of ${progress.total} quests completed"><strong>${progress.verified}/${progress.total}</strong><span>quests completed</span><div class="progress-track"><i style="width:${progress.percent}%"></i></div><small>${progress.percent}% complete</small></div></div><div class="classmate-heading"><div><h3>Classmates <span>${classroom.classmateCount}</span></h3><p>Only your own academic progress is visible to you.</p></div><button type="button" class="button secondary class-member-open" onclick="openClassMembers(${Number(classroom.id)})">View all members</button></div><div class="classmate-grid">${preview.map(classmateCard).join('')}</div></section>`;
  }).join('');
  shell(`<div class="journey-page student-list-page"><header class="journey-heading"><span class="journey-eyebrow">Learning community</span><h1>My classes</h1><p>See your completed progress and the classmates learning alongside you.</p></header>${classes.length?`<div class="my-classes-list">${cards}</div>`:`<section class="journey-empty">${emptyState('No classes yet','Enter an invitation code below to join your first class.')}</section>`}${joinClassForm()}</div>`);
}
async function redeemJoinCode(event){event.preventDefault();const button=event.submitter,error=document.querySelector('#join-code-error');button.disabled=true;button.textContent='Joining class';error.textContent='';try{const result=await api('/join-codes/redeem',{method:'POST',body:JSON.stringify({code:document.querySelector('#student-join-code').value})});showToast(`You joined ${result.section.name}.`);location.hash='class';await loadData()}catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Join class'}}
function questAction(q){const status=q.submission?.status||'pending';return status==='rejected'?'View feedback':status==='pending'?'Begin quest':status==='submitted'?'View submission':'View completed quest'}
function journeyItem(q,index,nextId){const status=q.submission?.status||'pending';return `<li class="journey-item ${status} ${q.id===nextId?'current':''}"><span class="journey-node" aria-hidden="true">${status==='verified'?icons.check:String(index+1).padStart(2,'0')}</span><article class="journey-card"><div class="journey-card-meta"><span>Quest ${String(index+1).padStart(2,'0')}</span>${statusPill(status)}</div><h3>${escapeHtml(q.title)}</h3><p>${escapeHtml(q.description)}</p><button class="journey-link" onclick="openQuest(${q.id})">${questAction(q)}</button></article></li>`}
function studentOverview(quests){const c=counts(quests),total=quests.length,previewQuests=quests.slice(0,4),firstName=escapeHtml(state.user.name.split(' ')[0]),next=quests.find(q=>q.submission?.status==='rejected')||quests.find(q=>!q.submission),pct=total?Math.round(c.verified/total*100):0;const message=next?(next.submission?'Your teacher has left feedback. Revise this quest to continue.':'Your next quest is ready when you are.'):(c.submitted?'Your work is with your teacher. Check back for a decision.':total?'Every quest is completed. Your journey is complete.':'Your teacher has not published any quests yet.');shell(`<div class="journey-page"><header class="journey-heading"><span class="journey-eyebrow">Rizal Life · Student journey</span><h1>Good to see you, ${firstName}.</h1><p>${escapeHtml(message)}</p></header><section class="journey-hero"><div class="journey-hero-copy"><span class="journey-eyebrow">Your learning journey</span><h2>${next?'The next chapter awaits.':total&&c.verified===total?'A journey completed.':'Explore your course, one quest at a time.'}</h2><p>${next?escapeHtml(next.title):total?'Your teacher-approved progress is shown here.':'New quests will appear here when your teacher publishes them.'}</p>${next?`<button class="button journey-primary" onclick="openQuest(${next.id})">${next.submission?'View feedback':'Begin quest'}</button>`:total&&c.submitted?`<a class="button journey-primary" href="#submissions">View submissions</a>`:''}</div><div class="journey-portrait"><img class="rizal-frame rizal-frame-rest" src="assets/jose-rizal-resting-v5.png" alt="José Rizal facing forward, greeting the student"><img class="rizal-frame rizal-frame-raised" src="assets/jose-rizal-waving-v3.png" alt="" aria-hidden="true"><img class="rizal-frame rizal-frame-wave" src="assets/jose-rizal-waving-v4.png" alt="" aria-hidden="true"></div></section><section class="journey-progress" aria-label="Completed course progress"><div><span class="journey-eyebrow">Course progress</span><h2>${c.verified} <small>of ${total} quests completed</small></h2><p>Only teacher-approved work counts toward completion.</p></div><div class="journey-progress-bar"><strong>${pct}%</strong><div class="progress-track"><i style="width:${pct}%"></i></div></div></section>${total?`<section class="journey-section"><div class="journey-section-head"><div><span class="journey-eyebrow">The path ahead</span><h2>Your quests</h2><p>Showing ${previewQuests.length} of ${total} quests. Open the full list whenever you need it.</p></div><a href="#quests">View all quests</a></div><ol class="journey-list">${previewQuests.map((q,i)=>journeyItem(q,i,next?.id)).join('')}</ol></section><section class="journey-milestone"><span class="milestone-icon">${icons.check}</span><div><span class="journey-eyebrow">Milestone</span><h2>${c.verified===total?'Course journey complete':c.verified?'Your first completed quest':'Your first milestone'}</h2><p>${c.verified===total?'Every published quest is completed.':c.verified?'Your teacher approved your work. Keep going.':'Complete a quest and receive teacher approval to earn your first milestone.'}</p></div><span class="milestone-state">${c.verified?'Earned':'To earn'}</span></section>`:`<section class="journey-empty">${emptyState('No quests yet','Your teacher will publish course activities here.')}</section>`}</div>`)}
function activityList(quests){const items=quests.filter(q=>q.submission).sort((a,b)=>b.submission.id-a.submission.id).slice(0,5);if(!items.length)return emptyState('No activity yet','Submit evidence for a quest to see updates here.');return `<div class="activity-list">${items.map(q=>`<button onclick="openQuest(${q.id})"><span class="activity-dot ${q.submission.status}">${q.submission.status==='verified'?icons.check:icons.clock}</span><span><b>${escapeHtml(q.title)}</b><small>${statusLabel(q.submission.status)} · ${formatDate(q.submission.reviewed_at||q.submission.submitted_at)}</small></span><strong>›</strong></button>`).join('')}</div>`}
function questNumber(q){return state.student.quests.indexOf(q)+1}
function questPreview(text,max=150){const clean=String(text||'').replace(/\s+/g,' ').trim();return clean.length>max?`${clean.slice(0,max).trimEnd()}…`:clean}
function questDueDate(q){return q.due_date||q.dueDate||null}
function questFilters(quests){return [['all','All'],['pending','Not submitted'],['submitted','For review'],['rejected','Needs revision'],['verified','Completed']].map(([id,label])=>`<button class="filter-button ${state.questFilter===id?'active':''}" onclick="setQuestFilter('${id}')" aria-pressed="${state.questFilter===id}">${label}<span>${id==='all'?quests.length:quests.filter(q=>(q.submission?.status||'pending')===id).length}</span></button>`).join('')}
function studentQuests(quests){const query=state.questSearch.trim().toLowerCase();let shown=quests.filter(q=>(state.questFilter==='all'||(q.submission?.status||'pending')===state.questFilter)&&(!query||q.title.toLowerCase().includes(query)||`quest ${String(questNumber(q)).padStart(2,'0')}`.includes(query)));if(state.questSort==='status')shown=[...shown].sort((a,b)=>statusLabel(a.submission?.status||'pending').localeCompare(statusLabel(b.submission?.status||'pending'))||questNumber(a)-questNumber(b));else shown=[...shown].sort((a,b)=>questNumber(a)-questNumber(b));shell(`<div class="journey-page student-list-page quest-list-page" tabindex="-1"><header class="journey-heading"><span class="journey-eyebrow">Your course activities</span><h1>Rizal quests</h1><p>Find each quest, review its status, and open it when you are ready to work.</p></header><section class="quest-list-tools" aria-label="Quest list controls"><div class="filter-row" aria-label="Filter quests by status">${questFilters(quests)}</div><div class="quest-search-row"><label class="search-box quest-search"><span aria-hidden="true">⌕</span><span class="sr-only">Search quests</span><input id="quest-search" type="search" value="${escapeHtml(state.questSearch)}" placeholder="Search by title or quest number" oninput="searchQuests(this,event)"></label><label class="quest-sort"><span>Sort</span><select onchange="sortQuests(this.value)"><option value="number" ${state.questSort==='number'?'selected':''}>Quest number</option><option value="status" ${state.questSort==='status'?'selected':''}>Status</option></select></label></div></section><p class="quest-result-count" aria-live="polite">${shown.length} of ${quests.length} quest${quests.length===1?'':'s'}</p><section class="quest-assignment-list" aria-label="Quest assignments">${shown.map(studentQuestRow).join('')||emptyState('No quests found',query?'Try another title, quest number, or status filter.':'There are no quests in this status.')}</section></div>`)}
function setQuestFilter(value){state.questFilter=value;studentQuests(state.student.quests)}
function searchQuests(input,event){state.questSearch=input.value;if(event?.isComposing)return;const start=input.selectionStart,end=input.selectionEnd;studentQuests(state.student.quests);restoreSearchFocus('#quest-search',start,end)}
function sortQuests(value){state.questSort=value;studentQuests(state.student.quests)}
function studentQuestRow(q){const status=q.submission?.status||'pending',number=String(questNumber(q)).padStart(2,'0'),due=questDueDate(q);return `<button type="button" class="quest-assignment-row ${status}" onclick="openQuest(${q.id})" aria-label="Open Quest ${number}: ${escapeHtml(q.title)}"><span class="quest-row-number">Quest ${number}</span><span class="quest-row-copy"><strong>${escapeHtml(q.title)}</strong><span>${escapeHtml(questPreview(q.description))}</span></span><span class="quest-row-meta">${due?`<time datetime="${escapeHtml(due)}">Due ${formatDate(due)}</time>`:''}${statusPill(status)}</span><svg class="quest-row-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></button>`}
function studentSubmissions(quests){const submissions=quests.filter(q=>q.submission).sort((a,b)=>b.submission.id-a.submission.id);shell(`<div class="journey-page student-list-page"><header class="journey-heading"><span class="journey-eyebrow">Your work and feedback</span><h1>My submissions</h1><p>See what your teacher has reviewed and what needs your attention.</p></header>${submissions.length?`<section class="submission-cards">${submissions.map(q=>`<article class="submission-card ${q.submission.status}"><div class="submission-card-head"><span class="quest-chapter">Quest ${String(quests.indexOf(q)+1).padStart(2,'0')}</span>${statusPill(q.submission.status)}</div><h2>${escapeHtml(q.title)}</h2><p>Submitted ${formatDate(q.submission.submitted_at)} · ${escapeHtml(q.submission.evidence_type)} evidence</p>${q.submission.feedback?`<div class="submission-feedback"><strong>Teacher feedback</strong><span>${escapeHtml(q.submission.feedback)}</span></div>`:''}<button class="journey-link" onclick="openQuest(${q.id})">${q.submission.status==='rejected'?'Revise quest':'View submission'}</button></article>`).join('')}</section>`:`<section class="journey-empty">${emptyState('No submissions yet','Open a quest to submit your first piece of evidence.') }<a class="button primary" href="#quests">Explore quests</a></section>`}</div>`)}
function evidenceDisplay(submission){if(submission.evidence_type==='image')return submission.evidence_url?`<a class="proof-image-link" href="${escapeHtml(submission.evidence_url)}" target="_blank" rel="noopener"><img class="proof-image" src="${escapeHtml(submission.evidence_url)}" alt="Submitted proof image"><span>Open full image ↗</span></a>`:'<p class="evidence-unavailable">Image preview is temporarily unavailable.</p>';if(submission.evidence_type==='link')return `<a class="evidence-link" href="${escapeHtml(submission.evidence)}" target="_blank" rel="noopener">${escapeHtml(submission.evidence)} ↗</a>`;return `<p class="preserve-lines">${escapeHtml(submission.evidence)}</p>`}
function setEvidenceType(type){const text=document.querySelector('#evidence-text-wrap'),image=document.querySelector('#evidence-image-wrap'),field=document.querySelector('#evidence-value');text.hidden=type==='image';image.hidden=type!=='image';field.required=type!=='image';}
function previewEvidenceImage(input){const file=input.files[0],preview=document.querySelector('#image-preview'),remove=document.querySelector('#remove-image');if(!file){preview.removeAttribute('src');preview.hidden=true;remove.hidden=true;return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){input.value='';showToast('Choose a JPG, PNG, or WebP image.','error');return}if(file.size>5*1024*1024){input.value='';showToast('The image must be 5 MB or smaller.','error');return}preview.src=URL.createObjectURL(file);preview.hidden=false;remove.hidden=false;}
function removeEvidenceImage(){const input=document.querySelector('#evidence-image'),preview=document.querySelector('#image-preview'),remove=document.querySelector('#remove-image');input.value='';preview.removeAttribute('src');preview.hidden=true;remove.hidden=true;}
function readImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The image could not be read.'));reader.readAsDataURL(file)})}
async function openProfile(mode='view'){profileCropData=null;closeProfileMenu();closeModal();openModal(modalSkeleton());try{const {profile}=await api('/profile');renderProfileModal(profile,mode)}catch(e){closeModal();showToast(e.message,'error')}}
function renderProfileModal(profile,mode){const editing=mode==='edit',student=profile.role==='student',roleLabel=student?'Student profile':'Teacher profile',identityFields=`<label class="form-field"><span>Full name</span><input id="profile-name" value="${escapeHtml(profile.name)}" ${student||!editing?'readonly aria-readonly="true"':'maxlength="100" required'}>${student?'<small>Your name is verified during registration and can only be corrected by a teacher.</small>':''}</label><label class="form-field"><span>Account email</span><input value="${escapeHtml(profile.email)}" readonly aria-readonly="true"><small>Email changes are restricted to protect account access.</small></label>${student&&profile.studentNumber?`<label class="form-field"><span>Student ID</span><input value="${escapeHtml(profile.studentNumber)}" readonly aria-readonly="true"></label>`:''}`;document.querySelector('#modal .dialog').innerHTML=`${dialogHeader(roleLabel,editing?'Edit profile':'View profile')}<div class="profile-summary">${avatarMarkup(profile,'profile',`${profile.name}'s profile picture`)}<div><b>${escapeHtml(profile.name)}</b><span>${escapeHtml(profile.email)}</span></div></div>${editing?`<form onsubmit="saveProfile(event,'${profile.role}')">${identityFields}<label class="form-field"><span>Profile picture</span><input id="profile-avatar-file" type="file" accept="image/jpeg,image/png,image/webp" onchange="openProfileCrop(this)"><small>Choose a JPG, PNG, or WebP image. Position and crop it before saving.</small><span id="profile-crop-status" class="profile-crop-status" aria-live="polite"></span></label>${profile.avatarUrl?'<button type="button" class="text-button danger-link remove-profile-photo" onclick="removeProfilePicture(this)">Remove profile picture</button>':''}<div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">Save changes</button></div></form>`:`${identityFields}<div class="dialog-actions"><button type="button" class="button secondary" onclick="openProfile('edit')">Edit Profile</button><button type="button" class="button primary" onclick="closeModal()">Done</button></div>`}<button type="button" class="profile-logout-link" onclick="confirmLogout()">${icons.logout}Log Out</button>`}
function updateOwnClassmateProfile(){for(const classroom of state.studentClasses?.classes||[])for(const classmate of classroom.classmates||[])if(classmate.isCurrentUser){classmate.name=state.user.name;classmate.avatarUrl=state.user.avatarUrl}}
async function saveProfile(event,role){event.preventDefault();const button=event.submitter,file=document.querySelector('#profile-avatar-file')?.files[0];if(file&&!['image/jpeg','image/png','image/webp'].includes(file.type)){showToast('Choose a JPG, PNG, or WebP image.','error');return}if(file&&!profileCropData){showToast('Crop your selected picture before saving.','error');return}button.disabled=true;button.textContent='Saving changes…';try{if(role==='teacher'){const {profile}=await api('/profile',{method:'PATCH',body:JSON.stringify({name:document.querySelector('#profile-name').value})});state.user.name=profile.name}if(file){const {avatarUrl}=await api('/profile/avatar',{method:'POST',body:JSON.stringify({image:{type:'image/jpeg',data:profileCropData}})});state.user.avatarUrl=avatarUrl}updateOwnClassmateProfile();closeModal();route();showToast('Profile changes saved.')}catch(e){showToast(e.message,'error');button.disabled=false;button.textContent='Save changes'}}
async function removeProfilePicture(button){button.disabled=true;button.textContent='Removing…';try{await api('/profile/avatar',{method:'DELETE'});state.user.avatarUrl=null;updateOwnClassmateProfile();closeModal();route();showToast('Profile picture removed.')}catch(e){showToast(e.message,'error');button.disabled=false;button.textContent='Remove profile picture'}}
function questInstructions(text){return String(text||'').split(/\n{2,}/).map(block=>`<p>${escapeHtml(block).replace(/\n/g,'<br>')}</p>`).join('')}
function questSubmissionForm(q){return `<form class="quest-submit-form" onsubmit="submitQuest(event,${q.id})"><div class="form-field"><span>Evidence type</span><div class="segmented"><label><input type="radio" name="evidence-type" value="link" checked onchange="setEvidenceType(this.value)"><span>Link</span></label><label><input type="radio" name="evidence-type" value="text" onchange="setEvidenceType(this.value)"><span>Text response</span></label><label><input type="radio" name="evidence-type" value="image" onchange="setEvidenceType(this.value)"><span>Upload image</span></label></div></div><label class="form-field" id="evidence-text-wrap"><span>Evidence</span><textarea id="evidence-value" rows="6" required placeholder="Paste a shareable link"></textarea><small>Choose Text response above if you want to write directly.</small></label><div class="form-field upload-field" id="evidence-image-wrap" hidden><span>Proof image</span><label class="upload-drop"><input id="evidence-image" type="file" accept="image/jpeg,image/png,image/webp" onchange="previewEvidenceImage(this)"><b>Choose an image</b><small>JPG, PNG, or WebP · maximum 5 MB</small></label><img id="image-preview" class="image-preview" alt="Selected proof preview" hidden><button id="remove-image" type="button" class="text-button danger-link" onclick="removeEvidenceImage()" hidden>Remove image</button></div><div class="quest-submit-actions"><button class="button primary">Submit for review</button><small>Your teacher will be notified when your evidence is submitted.</small></div></form>`}
function studentQuestDetail(id){const q=state.student.quests.find(item=>Number(item.id)===Number(id));if(!q){state.selectedQuestId=null;return studentQuests(state.student.quests)}const s=q.submission,status=s?.status||'pending',canSubmit=!s||status==='rejected',number=String(questNumber(q)).padStart(2,'0'),due=questDueDate(q);shell(`<article class="quest-detail-page" tabindex="-1"><button class="quest-back-button" onclick="backToQuests()">${icons.tasks}<span>Back to quests</span></button><header class="quest-detail-header"><div><span class="journey-eyebrow">Quest ${number}</span><h1>${escapeHtml(q.title)}</h1><div class="quest-detail-meta">${statusPill(status)}${due?`<time datetime="${escapeHtml(due)}">Due ${formatDate(due)}</time>`:''}</div></div></header><div class="quest-detail-layout"><div class="quest-detail-main"><section class="quest-detail-section"><span class="quest-detail-label">Instructions</span><div class="quest-instructions">${questInstructions(q.description)}</div></section><section class="quest-detail-section"><span class="quest-detail-label">Submission</span><h2>Evidence requirement</h2><p class="quest-requirement">${escapeHtml(q.requirement)}</p>${s?`<div class="quest-existing-submission"><div><strong>Your submission</strong><span>Submitted ${formatDate(s.submitted_at)} · ${escapeHtml(s.evidence_type)} evidence</span></div>${evidenceDisplay(s)}</div>`:''}${canSubmit?questSubmissionForm(q):`<p class="quest-locked-note">This submission is currently ${status==='submitted'?'waiting for teacher review':'completed'}.</p>`}</section></div><aside class="quest-feedback-panel"><span class="quest-detail-label">Teacher feedback</span>${s?.feedback?`<div class="quest-feedback-status">${statusPill(status)}${s.reviewed_at?`<time>Reviewed ${formatDate(s.reviewed_at)}</time>`:''}</div><p>${escapeHtml(s.feedback)}</p>`:`<div class="quest-feedback-empty">${s&&status==='submitted'?'Your work is awaiting review. Teacher remarks will appear here.':'No teacher feedback yet.'}</div>`}</aside></div></article>`)}
function openQuest(id){state.selectedQuestId=Number(id);if(state.page!=='quests'){location.hash='quests';return}studentQuestDetail(id);requestAnimationFrame(()=>document.querySelector('.quest-detail-page')?.focus?.())}
function backToQuests(){state.selectedQuestId=null;studentQuests(state.student.quests);requestAnimationFrame(()=>document.querySelector('.quest-list-page')?.focus())}
async function submitQuest(event,id){
  event.preventDefault();
  const button=event.submitter;
  button.disabled=true;
  button.textContent='Uploading…';
  try{
    const type=document.querySelector('input[name="evidence-type"]:checked').value;
    const payload={type};
    if(type==='image'){
      const file=document.querySelector('#evidence-image').files[0];
      if(!file)throw new Error('Choose an image to upload.');
      payload.image={name:file.name,type:file.type,data:await readImage(file)};
    }else payload.evidence=document.querySelector('#evidence-value').value;
    button.textContent='Submitting…';
    const {submission}=await api(`/quests/${id}/submit`,{method:'POST',body:JSON.stringify(payload)});
    const quest=state.student.quests.find(item=>Number(item.id)===Number(id));
    if(quest&&submission)quest.submission=submission;
    closeModal();
    route();
    showToast('Evidence submitted for teacher review.');
  }catch(e){
    showToast(e.message,'error');
    button.disabled=false;
    button.textContent='Submit for review';
  }
}
function renderTeacher(){if(state.page==='overview')return teacherOverview();if(state.page==='tasks')return teacherTasks();if(state.page==='reviews')return teacherReviews();teacherSections()}
function sectionSelector(allowAll=true){if(!state.sections.length)return '';return `<label class="section-select"><span>Section</span><select onchange="changeSection(this.value)">${allowAll&&state.sections.length>1?`<option value="all" ${state.sectionId==='all'?'selected':''}>All Sections</option>`:''}${state.sections.map(s=>`<option value="${s.id}" ${Number(s.id)===Number(state.sectionId)?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></label>`}
async function changeSection(id){state.sectionId=id==='all'?'all':Number(id);state.studentPage=1;state.reviewPage=1;state.reviewSection='all';localStorage.setItem('rizlife-section',state.sectionId);state.tasks=null;shell(contentSkeleton('Switching section'));try{state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`);route()}catch(e){errorScreen(e.message)}}
function teacherOverviewStats(d){
  const byStudent=new Map();
  for(const student of d.students){const current=byStudent.get(student.id)||{assigned:0,verified:0};current.assigned+=Number(student.taskCount||0);current.verified+=Number(student.verified||0);byStudent.set(student.id,current)}
  const total=byStudent.size;
  const completed=[...byStudent.values()].filter(student=>student.assigned>0&&student.verified===student.assigned).length;
  const returned=(d.reviews||[]).filter(item=>item.status==='rejected').length;
  const verified=d.students.reduce((sum,student)=>sum+Number(student.verified||0),0);
  const possible=d.students.reduce((sum,student)=>sum+Number(student.taskCount||0),0);
  return {total,completed,returned,verified,possible,percent:possible?Math.round(verified/possible*100):0,pending:d.queue.length};
}
function teacherOverview(){
  const firstName=state.user.name.split(' ')[0];
  if(!state.sectionId)return shell(`<div class="teacher-page">${teacherPageHeader("The scholar's desk",`Welcome, ${firstName}`,"Begin by creating a class for your students.",`<button class="button primary" onclick="openSectionForm()">${icons.plus}Create class</button>`)}<section class="scholar-empty">${emptyState('Your desk is ready','Create your first class to begin organizing learning expeditions.')}</section></div>`);
  const d=state.teacher;
  const {total,completed,returned,verified,possible,percent,pending}=teacherOverviewStats(d);
  shell(`<div class="teacher-page teacher-overview-page">${teacherPageHeader("The scholar's desk",`Welcome, ${firstName}`,`A clear view of ${escapeHtml(d.section.name)}.`,sectionSelector())}<section class="teacher-summary" aria-label="Class progress and review priorities"><div class="teacher-summary-progress"><div class="teacher-summary-heading"><span class="teacher-eyebrow">Completed task progress</span><strong>${percent}%</strong></div><div class="progress-track"><i style="width:${percent}%"></i></div><p>${verified} of ${possible} assigned tasks completed</p><small>${completed} of ${total} students completed every active task in their class.</small></div><div class="teacher-summary-review"><span class="teacher-eyebrow">Needs your review</span><strong>${pending}</strong><p>${pending===1?'submission awaiting a decision':'submissions awaiting a decision'}</p><a href="#reviews" class="button ${pending?'primary':'secondary'}">${pending?'Review submissions':'Open review desk'}</a></div></section><section class="teacher-metrics" aria-label="Class statistics">${teacherMetric('Total Students',total,`Across ${d.sections?.length||1} section${d.sections?.length===1?'':'s'}`,'people')}${teacherMetric('Pending Reviews',pending,'Awaiting a decision','review')}${teacherMetric('Students Completed',completed,'All active tasks completed','check')}${teacherMetric('Returned Submissions',returned,'Awaiting student revision','tasks')}</section>${d.sections?.length>1?sectionComparison(d.sections):''}<section class="teacher-workspace-grid"><article class="scholar-panel priority-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Tasks requiring attention</span><h2>Pending submissions</h2><p>Oldest work appears first.</p></div><a href="#reviews">View all ${pending}</a></div>${reviewQueue(d.queue.slice(0,5))}</article><article class="scholar-panel journal-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Latest changes</span><h2>Recent activity</h2></div></div>${recentActivityList(d.activity||[])}</article></section></div>`);
}
function recentActivityList(items){
  if(!items.length)return emptyState('No activity yet','Student submissions and class changes will appear here.');
  return `<div class="decision-list teacher-activity-list">${items.map(item=>{
    const action=item.kind==='submitted'?`submitted ${escapeHtml(item.title)}`:item.kind==='verified'?`completed ${escapeHtml(item.title)}`:item.kind==='rejected'?`was asked to revise ${escapeHtml(item.title)}`:`joined ${escapeHtml(item.section_name)}`;
    const click=item.kind!=='enrolled'&&state.teacher.reviews?.some(review=>Number(review.id)===Number(item.id))?` onclick="openReview(${Number(item.id)})"`:'';
    return `<${click?'button':'div'}${click} class="teacher-activity-item"><span class="activity-dot ${item.kind}">${item.kind==='verified'?icons.check:item.kind==='enrolled'?icons.people:icons.review}</span><span><b>${escapeHtml(item.student_name)}</b><small>${action}</small></span><time datetime="${escapeHtml(item.occurred_at)}">${formatDate(item.occurred_at)}</time></${click?'button':'div'}>`;
  }).join('')}</div>`;
}
function sectionComparison(items){return `<section class="scholar-panel section-comparison"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Section comparison</span><h2>Progress by section</h2><p>Completed task progress and pending workload.</p></div></div><div class="responsive-table"><table><thead><tr><th>Section</th><th>Students</th><th>Completed progress</th><th>Pending reviews</th></tr></thead><tbody>${items.map(s=>`<tr><td><button class="table-link" onclick="changeSection(${s.id})">${escapeHtml(s.name)}</button></td><td>${s.studentCount}</td><td><span class="mini-progress"><i style="width:${s.verifiedProgress}%"></i></span> ${s.verifiedProgress}%</td><td>${s.pendingReviews}</td></tr>`).join('')}</tbody></table></div></section>`}
function teacherPageHeader(eyebrow,title,description,action=''){return `<header class="teacher-page-header"><div><span class="teacher-eyebrow">${escapeHtml(eyebrow)}</span><h1>${escapeHtml(title)}</h1><p>${description}</p></div><div class="teacher-header-action teacher-header-tools">${notificationBell()}${action}</div></header>`}
function teacherMetric(label,value,note,icon){return `<article class="teacher-metric"><span class="teacher-metric-icon">${icons[icon]}</span><div><span>${escapeHtml(label)}</span><strong>${value}</strong><small>${escapeHtml(note)}</small></div></article>`}
function reviewQueue(items){if(!items.length)return emptyState('Review queue is clear','New student submissions will appear here.');return `<div class="queue-list">${items.map(s=>`<button onclick="openReview(${s.id})"><span class="avatar">${initials(s.student_name)}</span><span><b>${escapeHtml(s.student_name)}</b><small>${escapeHtml(s.title)}</small></span><time>${formatDate(s.submitted_at)}</time><strong>Review</strong></button>`).join('')}</div>`}
function recentDecisions(items=[]){if(!items.length)return emptyState('No decisions recorded','Approved and returned submissions will appear here.');return `<div class="decision-list">${items.map(s=>`<div><span class="activity-dot ${s.status}">${s.status==='verified'?icons.check:'!'}</span><span><b>${escapeHtml(s.student_name)}</b><small>${statusLabel(s.status)} · ${escapeHtml(s.title)}</small></span><time>${formatDate(s.reviewed_at)}</time></div>`).join('')}</div>`}
function studentProgressRows(items){if(!items.length)return emptyState('No students need attention','Students with returned work will appear here.');return `<div class="progress-rows">${items.map(s=>{const tasks=s.taskCount||state.teacher.taskCount,pct=tasks?Math.round(Number(s.verified)/tasks*100):0;return `<button onclick="openStudent('${s.id}',${s.section_id||state.sectionId})"><span class="avatar">${initials(s.name)}</span><span class="student-name"><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.section_name||'Student')}</small></span><span class="progress-cell"><span><i style="width:${pct}%"></i></span><small>${s.verified}/${tasks} verified</small></span><strong>${pct}%</strong></button>`}).join('')}</div>`}
async function teacherTasks(){if(!state.sectionId||state.sectionId==='all')return shell(`<div class="teacher-page">${teacherPageHeader('Learning expeditions','Course tasks','Choose one section to create or edit its tasks.',sectionSelector())}<section class="scholar-empty">${emptyState('Select a section','Tasks are section-specific so student records never become mixed.')}</section></div>`);if(!state.tasks){shell(contentSkeleton('Loading tasks'));try{state.tasks=await api(`/teacher/quests?sectionId=${state.sectionId}`)}catch(e){return errorScreen(e.message)}}const active=state.tasks.quests.filter(q=>q.active),archived=state.tasks.quests.filter(q=>!q.active);shell(`<div class="teacher-page">${teacherPageHeader('Learning expeditions','Course tasks',`Create and maintain the quests published to ${escapeHtml(state.teacher.section.name)}.`,`<div class="header-actions">${sectionSelector()}<button class="button primary" onclick="openTaskForm()">${icons.plus}Create task</button></div>`)}<section class="scholar-panel table-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Published expeditions</span><h2>Active tasks</h2><p>${active.length} visible to enrolled students.</p></div></div>${taskAdminTable(active)}</section>${archived.length?`<section class="scholar-panel table-panel archived-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Archive</span><h2>Archived tasks</h2><p>Hidden from students.</p></div></div>${taskAdminTable(archived)}</section>`:''}</div>`)}
function taskAdminTable(items){return items.length?`<div class="responsive-table"><table><thead><tr><th>Task</th><th>Evidence requirement</th><th>Updated</th><th></th></tr></thead><tbody>${items.map(q=>`<tr><td><span class="table-primary">${escapeHtml(q.title)}</span><small>${escapeHtml(q.description)}</small></td><td>${escapeHtml(q.requirement)}</td><td>${formatDate(q.updated_at)}</td><td><button class="more-button" onclick="openTaskForm(${q.id})">Edit</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No active tasks','Create the first task for this course.')}
function openTaskForm(id=null){const q=id?state.tasks.quests.find(item=>item.id===id):null;openModal(`${dialogHeader(q?'Edit task':'New task',q?.title||'Create a course task')}<form onsubmit="saveTask(event,${id||'null'})"><label class="form-field"><span>Task title</span><input id="task-title" maxlength="100" required value="${escapeHtml(q?.title||'')}"></label><label class="form-field"><span>Instructions</span><textarea id="task-description" rows="5" required>${escapeHtml(q?.description||'')}</textarea><small>Explain what the student needs to do in clear, direct language.</small></label><label class="form-field"><span>Evidence requirement</span><textarea id="task-requirement" rows="3" required>${escapeHtml(q?.requirement||'')}</textarea><small>Specify whether students should provide a link, short response, or image link.</small></label><div class="dialog-actions split">${q?`<button type="button" class="button ${q.active?'danger-text':'secondary'}" onclick="setTaskStatus(${q.id},${q.active?0:1})">${q.active?'Archive task':'Restore task'}</button>`:'<span></span>'}<div><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">${q?'Save changes':'Create task'}</button></div></div></form>`,true)}
function applySavedTask(quest){
  if(!state.tasks)state.tasks={quests:[]};
  const index=state.tasks.quests.findIndex(item=>Number(item.id)===Number(quest.id));
  if(index>=0)state.tasks.quests[index]=quest;
  else state.tasks.quests.push(quest);
  state.tasks.quests.sort((a,b)=>Number(a.id)-Number(b.id));
}
async function refreshTeacherSummary(sectionId=state.sectionId){
  try{
    const dashboard=await api(`/teacher/dashboard?sectionId=${sectionId}`);
    if(state.user?.role==='teacher'&&String(state.sectionId)===String(sectionId)){
      state.teacher=dashboard;
      if(state.page!=='tasks')route();
    }
  }catch(error){console.warn('Dashboard will retry its update:',error.message)}
}
async function saveTask(event,id){
  event.preventDefault();
  const button=event.submitter;
  button.disabled=true;
  const payload={title:document.querySelector('#task-title').value,description:document.querySelector('#task-description').value,requirement:document.querySelector('#task-requirement').value,sectionId:state.sectionId};
  try{
    const {quest}=await api(id?`/teacher/quests/${id}`:'/teacher/quests',{method:id?'PUT':'POST',body:JSON.stringify(payload)});
    applySavedTask(quest);
    closeModal();
    route();
    showToast(id?'Task updated.':'Task created and published.');
    void refreshTeacherSummary();
  }catch(e){showToast(e.message,'error');button.disabled=false}
}
async function setTaskStatus(id,active){
  try{
    const {quest}=await api(`/teacher/quests/${id}/status`,{method:'PATCH',body:JSON.stringify({active:Boolean(active),sectionId:state.sectionId})});
    applySavedTask(quest);
    closeModal();
    route();
    showToast(active?'Task restored.':'Task archived.');
    void refreshTeacherSummary();
  }catch(e){showToast(e.message,'error')}
}
function teacherReviewItems(all,status,search,sort,section='all'){
  const statusMap={pending:'submitted',verified:'verified',returned:'rejected'};
  const term=search.trim().toLocaleLowerCase();
  return all.filter(item=>(status==='all'||item.status===statusMap[status])&&(section==='all'||String(item.section_id)===String(section))&&`${item.student_name} ${item.title}`.toLocaleLowerCase().includes(term))
    .sort((a,b)=>(sort==='newest'?-1:1)*(new Date(a.submitted_at)-new Date(b.submitted_at)));
}
function teacherReviews(){
  if(!state.sectionId)return shell(`<div class="teacher-page">${teacherPageHeader('Manuscript review','Submission reviews','Create a class before reviewing submissions.')}<section class="scholar-empty">${emptyState('No class selected','Create a class from the Class page.')}</section></div>`);
  const all=state.teacher.reviews||state.teacher.queue||[];
  const statusMap={pending:'submitted',verified:'verified',returned:'rejected'};
  const term=state.reviewSearch.trim();
  const sectionRows=[...new Map(all.filter(item=>item.section_id).map(item=>[String(item.section_id),{id:String(item.section_id),name:item.section_name||'Section'}])).values()].sort((a,b)=>a.name.localeCompare(b.name));
  if(state.reviewSection!=='all'&&!sectionRows.some(section=>section.id===String(state.reviewSection)))state.reviewSection='all';
  const scoped=teacherReviewItems(all,'all','',state.reviewSort,state.reviewSection);
  const items=teacherReviewItems(all,state.reviewStatus,term,state.reviewSort,state.reviewSection);
  const pageSize=20,totalPages=Math.max(1,Math.ceil(items.length/pageSize));
  state.reviewPage=Math.min(state.reviewPage,totalPages);
  const pageItems=items.slice((state.reviewPage-1)*pageSize,state.reviewPage*pageSize);
  const reviewCounts={all:scoped.length,pending:scoped.filter(item=>item.status==='submitted').length,returned:scoped.filter(item=>item.status==='rejected').length,verified:scoped.filter(item=>item.status==='verified').length};
  const filters=[['all','All'],['pending','Pending'],['returned','Returned'],['verified','Completed']];
  const tabs=filters.map(([key,label])=>`<button type="button" class="review-filter ${key==='pending'&&reviewCounts.pending?'attention':''} ${state.reviewStatus===key?'active':''}" onclick="setReviewStatus('${key}')" aria-pressed="${state.reviewStatus===key}">${label}<span>${reviewCounts[key]}</span></button>`).join('');
  const emptyCopy=term?['No submissions match your search','Try another student name or task title.']:state.reviewStatus==='pending'?["You're all caught up",'No submissions are waiting for review.']:state.reviewStatus==='verified'?['No completed reviews yet','Completed submissions will appear here.']:state.reviewStatus==='returned'?['No returned submissions','Work returned for revision will appear here.']:['No submissions available','Student submissions will appear here.'];
  const resetActive=Boolean(term||state.reviewSection!=='all'||state.reviewSort!=='oldest');
  const sectionFilter=sectionRows.length>1?`<label class="review-select"><span>Section</span><select aria-label="Filter by section" onchange="state.reviewSection=this.value;state.reviewPage=1;teacherReviews()"><option value="all">All sections</option>${sectionRows.map(section=>`<option value="${escapeHtml(section.id)}" ${String(state.reviewSection)===section.id?'selected':''}>${escapeHtml(section.name)}</option>`).join('')}</select></label>`:'';
  const summary=[['all','Total submissions'],['pending','Pending reviews'],['returned','Returned'],['verified','Completed']].map(([key,label])=>`<button type="button" class="review-summary-item ${state.reviewStatus===key?'active':''}" onclick="setReviewStatus('${key}')" aria-pressed="${state.reviewStatus===key}"><span>${label}</span><strong>${reviewCounts[key]}</strong></button>`).join('');
  shell(`<div class="teacher-page review-page">${teacherPageHeader('Manuscript review','Submission reviews',`Review work from ${escapeHtml(state.teacher.section.name)} without losing your place.`,sectionSelector())}<section class="scholar-panel review-desk"><div class="review-summary" aria-label="Submission summary">${summary}</div><div class="review-filters" aria-label="Filter submissions by status">${tabs}</div><div class="review-controls"><label class="search-box"><span aria-hidden="true">⌕</span><input id="review-search" value="${escapeHtml(state.reviewSearch)}" oninput="searchReviews(this,event)" placeholder="Search student or task" aria-label="Search student or task"></label>${sectionFilter}<label class="review-select"><span>Sort</span><select aria-label="Sort submissions" onchange="state.reviewSort=this.value;state.reviewPage=1;teacherReviews()"><option value="oldest" ${state.reviewSort==='oldest'?'selected':''}>Oldest first</option><option value="newest" ${state.reviewSort==='newest'?'selected':''}>Newest first</option></select></label>${resetActive?'<button type="button" class="review-reset" onclick="resetReviewControls()">Reset</button>':''}</div>${pageItems.length?`<div class="review-results">${pageItems.map(reviewListItem).join('')}</div>`:`<div class="review-empty">${emptyState(emptyCopy[0],emptyCopy[1])}</div>`}${pagination('review',state.reviewPage,totalPages,items.length)}</section></div>`);
}
function setReviewStatus(value){state.reviewStatus=value;state.reviewPage=1;teacherReviews()}
function resetReviewControls(){state.reviewSearch='';state.reviewSection='all';state.reviewSort='oldest';state.reviewPage=1;teacherReviews()}
function reviewListItem(item){return `<button type="button" class="review-result ${item.status}" onclick="openReview(${Number(item.id)})"><span class="avatar">${initials(item.student_name)}</span><span class="review-result-copy"><b>${escapeHtml(item.student_name)}</b><small>${escapeHtml(item.title)}</small></span><span class="review-result-context"><small>${escapeHtml(item.section_name||'Section')}</small><time datetime="${escapeHtml(item.submitted_at)}">${formatDate(item.submitted_at)}</time></span>${statusPill(item.status)}<span class="review-open">Open review <b aria-hidden="true">›</b></span></button>`}
function restoreSearchFocus(selector,start,end){const input=document.querySelector(selector);if(!input)return;input.focus({preventScroll:true});input.setSelectionRange(start,end)}
function searchReviews(input,event){state.reviewSearch=input.value;state.reviewPage=1;if(event?.isComposing)return;const start=input.selectionStart,end=input.selectionEnd;teacherReviews();restoreSearchFocus('#review-search',start,end)}
function openReview(id){
  const item=(state.teacher.reviews||state.teacher.queue||[]).find(row=>Number(row.id)===Number(id))||(state.teacher.notifications||[]).find(row=>Number(row.id)===Number(id));
  if(!item)return showToast('This submission is no longer available.','error');
  closeModal();
  const pending=item.status==='submitted';
  const feedback=item.feedback?`<div class="feedback-block"><span>Teacher feedback</span><p>${escapeHtml(item.feedback)}</p></div>`:'';
  openModal(`${dialogHeader('Submission review',item.title)}<div class="student-strip"><span class="avatar">${initials(item.student_name)}</span><div><b>${escapeHtml(item.student_name)}</b><small>${escapeHtml(item.section_name||'')} · Submitted ${formatDate(item.submitted_at)}</small></div></div><div class="review-detail-status">${statusPill(item.status)}<time datetime="${escapeHtml(item.submitted_at)}">${formatDate(item.submitted_at)}</time></div><div class="detail-block"><span>Evidence · ${escapeHtml(item.evidence_type)}</span>${evidenceDisplay(item)}</div>${feedback}${pending?`<label class="form-field"><span>Teacher remarks <small>(optional)</small></span><textarea id="review-feedback" rows="4" maxlength="2000" placeholder="Add specific, helpful feedback"></textarea></label><div class="dialog-actions review-decision-actions"><button type="button" class="button danger-text" onclick="confirmReviewDecision(${Number(id)},'rejected')">Return for revision</button><button type="button" class="button primary" onclick="confirmReviewDecision(${Number(id)},'verified')">${icons.check}Mark completed</button></div>`:'<div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Close</button></div>'}`,true);
}
function confirmReviewDecision(id,status){
  const item=(state.teacher.reviews||state.teacher.queue||[]).find(row=>Number(row.id)===Number(id));
  if(!item||item.status!=='submitted')return showToast('This submission has already been reviewed.','error');
  const feedback=document.querySelector('#review-feedback')?.value.trim()||'';
  state.pendingReviewDecision={id,status,feedback,sectionId:item.section_id};
  const title=status==='verified'?'Mark submission completed?':'Return for revision?';
  const action=status==='verified'?'Verification will count toward the student’s completed tasks.':'The student will see this work as needing revision.';
  document.querySelector('#modal .dialog').innerHTML=`${dialogHeader('Confirm decision',title)}<p class="dialog-description">${escapeHtml(item.student_name)} · ${escapeHtml(item.title)}</p><p class="review-confirm-copy">${action}</p>${feedback?`<div class="feedback-block"><span>Your remarks</span><p>${escapeHtml(feedback)}</p></div>`:''}<div class="dialog-actions"><button type="button" class="button secondary" onclick="returnToReview()">Back</button><button type="button" class="button ${status==='verified'?'primary':'danger'}" onclick="decideSubmission(this)">${status==='verified'?'Mark completed':'Return for revision'}</button></div>`;
}
function returnToReview(){const decision=state.pendingReviewDecision;if(!decision)return;openReview(decision.id);const field=document.querySelector('#review-feedback');if(field)field.value=decision.feedback}
async function decideSubmission(button){
  const decision=state.pendingReviewDecision;
  if(!decision||button.disabled)return;
  button.disabled=true;
  button.textContent='Saving decision…';
  try{
    await api(`/teacher/submissions/${decision.id}`,{method:'PATCH',body:JSON.stringify({status:decision.status,feedback:decision.feedback,sectionId:decision.sectionId})});
    state.pendingReviewDecision=null;
    closeModal();
    showToast(decision.status==='verified'?'Submission completed.':'Submission returned for revision.');
    try{state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`);route()}
    catch(error){showToast('Decision saved. The dashboard will update shortly.');window.refreshLiveData?.()}
  }catch(error){
    showToast(error.message,'error');
    button.disabled=false;
    button.textContent=decision.status==='verified'?'Mark completed':'Return for revision';
  }
}
function teacherSections(){const selected=state.sections.find(s=>Number(s.id)===Number(state.sectionId)),term=state.studentSearch.toLowerCase();let students=state.teacher.students.filter(s=>`${s.name} ${s.email||''} ${s.section_name||''}`.toLowerCase().includes(term));if(state.studentStatus==='revision')students=students.filter(s=>s.rejected>0);if(state.studentStatus==='review')students=students.filter(s=>s.submitted>0);if(state.studentStatus==='complete')students=students.filter(s=>s.taskCount&&s.verified===s.taskCount);students.sort((a,b)=>state.studentSort==='progress'?(b.verified/Math.max(1,b.taskCount)-a.verified/Math.max(1,a.taskCount)):state.studentSort==='recent'?(new Date(b.recent_at||0)-new Date(a.recent_at||0)):a.name.localeCompare(b.name));const pageSize=25,totalPages=Math.max(1,Math.ceil(students.length/pageSize));state.studentPage=Math.min(state.studentPage,totalPages);const pageItems=students.slice((state.studentPage-1)*pageSize,state.studentPage*pageSize),scope=selected?.name||'All Sections';shell(`<div class="teacher-page">${teacherPageHeader('Learning community','Students','Search, filter, and manage large rosters by section.',`<div class="header-actions">${sectionSelector()}<button class="button primary" onclick="openSectionForm()">${icons.plus}Create class</button></div>`)}<section class="section-grid compact-sections">${state.sections.map(s=>`<button class="section-card ${Number(s.id)===Number(state.sectionId)?'active':''}" onclick="changeSection(${s.id})"><span class="section-card-mark">${icons.people}</span><b>${escapeHtml(s.name)}</b><span>${s.studentCount} students · ${s.taskCount} tasks</span></button>`).join('')}</section><section class="scholar-panel class-list-panel"><div class="list-toolbar"><div><span class="teacher-eyebrow">Student directory</span><h2>${escapeHtml(scope)}</h2><p>Showing ${students.length} of ${state.teacher.students.length} enrollment records</p></div>${selected?`<div class="header-actions"><button class="button primary" onclick="openJoinCodeManager()">Class invitation code</button></div>`:''}</div><div class="directory-filters"><label class="search-box"><span aria-hidden="true">⌕</span><input id="student-search" value="${escapeHtml(state.studentSearch)}" oninput="searchStudents(this,event)" placeholder="Search name, email, or section" aria-label="Search students"></label><select aria-label="Filter students" onchange="state.studentStatus=this.value;state.studentPage=1;teacherSections()"><option value="all">All statuses</option><option value="revision" ${state.studentStatus==='revision'?'selected':''}>Needs revision</option><option value="review" ${state.studentStatus==='review'?'selected':''}>Awaiting review</option><option value="complete" ${state.studentStatus==='complete'?'selected':''}>Journey complete</option></select><select aria-label="Sort students" onchange="state.studentSort=this.value;state.studentPage=1;teacherSections()"><option value="name">Alphabetical</option><option value="progress" ${state.studentSort==='progress'?'selected':''}>Progress</option><option value="recent" ${state.studentSort==='recent'?'selected':''}>Recent activity</option></select></div>${sectionStudentRows(pageItems)}${pagination('student',state.studentPage,totalPages,students.length)}${selected?`<div class="class-actions"><button class="button secondary" onclick="openSectionForm(${selected.id})">Edit section</button><button class="button danger-text" onclick="deleteClass(${selected.id})">Delete section</button></div>`:''}</section></div>`)}
function searchStudents(input,event){state.studentSearch=input.value;state.studentPage=1;if(event?.isComposing)return;const start=input.selectionStart,end=input.selectionEnd;teacherSections();restoreSearchFocus('#student-search',start,end)}
async function openJoinCodeManager(){openModal(modalSkeleton());try{const status=await api(`/teacher/sections/${state.sectionId}/join-code`),code=status.code?escapeHtml(status.code):'';state.latestJoinCode=status.code||null;const activeCode=status.recoverable?`<p class="dialog-description">Students use this permanent code after creating or signing in to their student account.</p><div class="join-code-display">${code}</div>`:status.active?`<div class="invite-notice">This is an older code created before code recovery was available. It still works for students, but its text cannot be displayed again. Replace it once to create a copyable code.</div>`:'<p class="dialog-description">No active join code exists for this class.</p>';document.querySelector('#modal .dialog').innerHTML=`${dialogHeader('Class join code',state.teacher.section.name)}<div class="invite-explainer"><span>${icons.people}</span><div><b>Invite students with one permanent code</b><p>Each section keeps one code until you deliberately replace or revoke it.</p></div></div>${activeCode}<div class="dialog-actions split">${status.active?'<button class="button danger-text" onclick="revokeJoinCode()">Revoke code</button>':'<span></span>'}<div>${status.recoverable?'<button class="button secondary" onclick="copyJoinCode()">Copy code</button>':''}<button class="button secondary" onclick="closeModal()">Done</button><button class="button primary" onclick="generateJoinCode()">${status.active?'Replace code':'Create join code'}</button></div></div>`}catch(e){closeModal();showToast(e.message,'error')}}
async function copyJoinCode(){if(!state.latestJoinCode)return;try{await navigator.clipboard.writeText(state.latestJoinCode);showToast('Invitation code copied.')}catch{showToast('Copy was blocked. Select the code and copy it manually.','error')}}
async function generateJoinCode(){const result=await api(`/teacher/sections/${state.sectionId}/join-code`,{method:'POST'}),code=escapeHtml(result.code);state.latestJoinCode=result.code;document.querySelector('#modal .dialog').innerHTML=`${dialogHeader('Share this join code',result.sectionName)}<p class="dialog-description">Students use this permanent code to create an account or join the section. It remains valid until you replace or revoke it.</p><div class="join-code-display" id="teacher-join-code">${code}</div><div class="dialog-actions"><button class="button secondary" onclick="copyJoinCode()">Copy code</button><button class="button primary" onclick="closeModal()">Done</button></div>`}
async function revokeJoinCode(){try{await api(`/teacher/sections/${state.sectionId}/join-code`,{method:'DELETE'});showToast('The join code was revoked.');closeModal();openJoinCodeManager()}catch(e){showToast(e.message,'error')}}
function enhanceTeacherPage(){if(state.page!=='class'||!state.sectionId)return;const toolbar=document.querySelector('.class-list-panel .list-toolbar');if(!toolbar)return;const requests=state.teacher.pendingRequests||[];if(requests.length&&!document.querySelector('.pending-registration-panel')){const panel=document.createElement('section');panel.className='pending-registration-panel';panel.innerHTML=`<div class="pending-registration-head"><div><span class="teacher-eyebrow">Teacher approval required</span><h3>Pending student registrations</h3><p>Compare each request with your official class list before approving access.</p></div><strong>${requests.length}</strong></div><div class="pending-registration-list">${requests.map(request=>`<article><span class="avatar">${initials(request.name)}</span><div><b>${escapeHtml(request.name)}</b><small>${escapeHtml(request.email)} · Student ID ${escapeHtml(request.student_number)} · ${formatDate(request.created_at)}</small></div><div><button class="button danger-text" onclick="reviewRegistration(${request.section_id},${request.id},'rejected',this)">Reject</button><button class="button primary" onclick="reviewRegistration(${request.section_id},${request.id},'approved',this)">Approve</button></div></article>`).join('')}</div>`;toolbar.after(panel)}}
async function reviewRegistration(sectionId,requestId,decision,button){if(decision==='rejected'&&!confirm('Reject this registration request? The student will not be able to sign in.'))return;const actions=button.closest('article').querySelectorAll('button');actions.forEach(item=>item.disabled=true);try{await api(`/teacher/sections/${sectionId}/registration-requests/${requestId}`,{method:'PATCH',body:JSON.stringify({decision})});showToast(decision==='approved'?'Student approved and enrolled.':'Registration rejected.');await loadData()}catch(e){showToast(e.message,'error');actions.forEach(item=>item.disabled=false)}}
function downloadRosterTemplate(){const csv='Student Name,Student Email,Student ID,Section\r\nJM Gatchalian,jmgatchalian@student.apc.edu.ph,2026-00001,IT242-A\r\n';const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='rizlife-student-import-template.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function openStudentImport(){const defaultSection=state.sectionId==='all'?'':state.sectionId;openModal(`${dialogHeader('Student directory','Import students')}<p class="dialog-description">Upload a CSV or Excel roster. Review every row before creating invitations or enrollments.</p><div class="import-template"><div><b>Required columns</b><span>Student Name and Student Email. Student ID and Section are optional.</span></div><button class="text-button" onclick="downloadRosterTemplate()">Download CSV template</button></div><form onsubmit="previewStudentImport(event)"><label class="form-field"><span>Default section</span><select id="import-section"><option value="">Use the Section column</option>${state.sections.map(section=>`<option value="${section.id}" ${Number(section.id)===Number(defaultSection)?'selected':''}>${escapeHtml(section.name)}</option>`).join('')}</select><small>Rows with a Section value use that section. Otherwise this default is used.</small></label><label class="form-field upload-field"><span>Class roster</span><label class="upload-drop"><input id="import-file" type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required><b>Choose a CSV or Excel file</b><small>Maximum 2.5 MB and 500 student rows</small></label></label><p class="form-error" id="import-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">Preview import</button></div></form>`,true)}
async function fileAsBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('The roster file could not be read.'));reader.readAsDataURL(file)})}
async function previewStudentImport(event){event.preventDefault();const file=document.querySelector('#import-file').files[0],button=event.submitter,error=document.querySelector('#import-error');if(!file)return;button.disabled=true;button.textContent='Checking roster';error.textContent='';try{const result=await api('/teacher/students/import/preview',{method:'POST',body:JSON.stringify({file:{name:file.name,data:await fileAsBase64(file)},defaultSectionId:document.querySelector('#import-section').value})});state.importPreview=result;renderImportPreview()}catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Preview import'}}
function importStatus(row){if(row.status==='invalid')return 'Needs correction';if(row.status==='duplicate')return 'Already enrolled';return row.action==='enroll'?'Existing account':'New invitation'}
function renderImportPreview(){const result=state.importPreview,valid=result.rows.filter(row=>row.status==='valid');document.querySelector('#modal .dialog').innerHTML=`${dialogHeader('Import preview',`${result.summary.total} student records`)}<div class="import-summary"><span><strong>${result.summary.valid}</strong>Ready</span><span><strong>${result.summary.duplicates}</strong>Duplicates</span><span><strong>${result.summary.invalid}</strong>Need correction</span></div><p class="dialog-description">Only ready rows will be imported. Correct invalid rows in the spreadsheet and upload it again if needed.</p><div class="import-preview-table"><table><thead><tr><th>Row</th><th>Student</th><th>Section</th><th>Status</th></tr></thead><tbody>${result.rows.map(row=>`<tr class="${row.status}"><td>${row.row}</td><td><b>${escapeHtml(row.name||'Missing name')}</b><small>${escapeHtml(row.email||'Missing email')}${row.studentNumber?` · ${escapeHtml(row.studentNumber)}`:''}</small>${row.errors.length?`<em>${escapeHtml(row.errors.join(' '))}</em>`:''}</td><td>${escapeHtml(row.sectionName||'Not assigned')}</td><td><span class="import-status">${importStatus(row)}</span></td></tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button class="button secondary" onclick="openStudentImport()">Choose another file</button><button class="button primary" ${valid.length?'':'disabled'} onclick="confirmStudentImport(this)">Import ${valid.length} students</button></div>`}
async function confirmStudentImport(button){const rows=state.importPreview.rows.filter(row=>row.status==='valid');if(!rows.length)return;button.disabled=true;button.textContent='Importing students';try{const result=await api('/teacher/students/import',{method:'POST',body:JSON.stringify({rows})}),invitations=result.results.filter(row=>row.status==='invited');state.preparedInvitations=invitations;document.querySelector('#modal .dialog').innerHTML=`${dialogHeader('Import complete','Student roster updated')}<div class="import-summary"><span><strong>${result.summary.enrolled}</strong>Enrolled</span><span><strong>${result.summary.invited}</strong>Invitations</span><span><strong>${result.summary.skipped}</strong>Skipped</span><span><strong>${result.summary.failed}</strong>Failed</span></div>${invitations.length?`<p class="dialog-description">Open each prepared message and send it from your APC Outlook account. RizLife never accesses your Outlook password.</p><div class="prepared-invitations">${invitations.map((row,index)=>`<div><span><b>${escapeHtml(row.name)}</b><small>${escapeHtml(row.email)} · ${escapeHtml(row.sectionName)}</small></span><button class="button secondary" onclick="showOutlookInvitation(state.preparedInvitations[${index}])">Prepare email</button></div>`).join('')}</div>`:''}${result.summary.failed?`<div class="import-result-list">${result.results.filter(row=>row.status==='failed').map(row=>`<p><b>Row ${row.row}</b> ${escapeHtml(row.email)} — ${escapeHtml(row.message)}</p>`).join('')}</div>`:''}<div class="dialog-actions"><button class="button primary" onclick="closeModal();loadData()">Done</button></div>`}catch(e){showToast(e.message,'error');button.disabled=false;button.textContent=`Import ${rows.length} students`}}
function prepareOutlookWindow(){const popup=window.open('','_blank');if(!popup){showToast('Allow pop-ups for RizLife so Outlook can open.','error');return null}popup.document.title='Preparing Outlook invitation';popup.document.body.innerHTML='<p style="font:16px system-ui;padding:32px;color:#263238">Preparing your secure Outlook invitation…</p>';return popup}
function outlookInvitationContent(invitation){return{subject:`Invitation to join ${invitation.sectionName} in RizLife`,body:`Hello ${invitation.name},\n\nYou have been invited to join ${invitation.sectionName} in RizLife.\n\nOpen your secure invitation:\n${invitation.invitationUrl}\n\nThis one-time invitation is intended for your school account and will expire.`}}
function openOutlookInvitation(invitation,popup=null){if(!invitation?.invitationUrl){popup?.close();return showToast('The invitation link is unavailable.','error')}const{subject,body}=outlookInvitationContent(invitation),url=`https://outlook.office.com/mail/deeplink/compose?to=${encodeURIComponent(invitation.email)}&subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;if(popup){popup.location.replace(url);popup.opener=null}else window.open(url,'_blank','noopener')}
function showOutlookInvitation(invitation){state.pendingOutlookInvitation=invitation;const{subject,body}=outlookInvitationContent(invitation);openModal(`${dialogHeader('Invitation ready',invitation.name)}<div class="invite-explainer"><span>${icons.submit}</span><div><b>Send from your Outlook account</b><p>If Microsoft asks you to sign in and opens your Inbox, return here and click Open Outlook again.</p></div></div><label class="form-field"><span>Recipient</span><input value="${escapeHtml(invitation.email)}" readonly></label><label class="form-field"><span>Subject</span><input value="${escapeHtml(subject)}" readonly></label><label class="form-field"><span>Invitation message</span><textarea rows="8" readonly>${escapeHtml(body)}</textarea></label><div class="dialog-actions split"><button class="button secondary" onclick="copyOutlookInvitation()">Copy invitation</button><div><button class="button secondary" onclick="closeModal()">Done</button><button class="button primary" onclick="openOutlookInvitation(state.pendingOutlookInvitation)">Open Outlook again</button></div></div>`,true)}
async function copyOutlookInvitation(){const invitation=state.pendingOutlookInvitation;if(!invitation)return;const{subject,body}=outlookInvitationContent(invitation);try{await navigator.clipboard.writeText(`To: ${invitation.email}\nSubject: ${subject}\n\n${body}`);showToast('Invitation copied. Paste it into a new Outlook email.')}catch{showToast('Copy was blocked. Select the invitation message and copy it manually.','error')}}
function pagination(kind,page,totalPages,total){if(totalPages<=1)return `<p class="result-count">${total} result${total===1?'':'s'}</p>`;return `<nav class="pagination" aria-label="${kind} pages"><button class="button secondary" ${page===1?'disabled':''} onclick="setPage('${kind}',${page-1})">Previous</button><span>Page ${page} of ${totalPages} · ${total} results</span><button class="button secondary" ${page===totalPages?'disabled':''} onclick="setPage('${kind}',${page+1})">Next</button></nav>`}
function setPage(kind,page){if(kind==='student'){state.studentPage=page;teacherSections()}else{state.reviewPage=page;teacherReviews()}}
function sectionStudentRows(students){if(!students.length)return emptyState('No matching students','Share the class invitation code so students can register and join.');return `<div class="section-students">${students.map(s=>`<div><button class="student-main" onclick="openStudent('${s.id}',${s.section_id||state.sectionId})"><span class="avatar">${initials(s.name)}</span><span><b>${escapeHtml(s.name)}</b><small>${s.invitationPending?`Account setup incomplete · ${escapeHtml(s.email)}`:`${escapeHtml(s.section_name||'')} · ${s.verified}/${s.taskCount||state.teacher.taskCount} tasks completed`}</small></span></button><div class="student-row-actions">${state.sectionId!=='all'?`<button class="text-button danger-link" onclick="removeStudent('${s.id}')">Remove</button>`:''}</div></div>`).join('')}</div>`}
async function resendStudentInvitation(id,button){const popup=prepareOutlookWindow();if(!popup)return;button.disabled=true;button.textContent='Preparing';try{const result=await api(`/teacher/sections/${state.sectionId}/students/${id}/invitation`,{method:'POST'});openOutlookInvitation(result,popup);showToast('A new Outlook invitation is ready.');await loadData();showOutlookInvitation(result)}catch(e){popup.close();showToast(e.message,'error');button.disabled=false;button.textContent='Prepare invitation'}}
function openSectionForm(id=null){const current=id?state.sections.find(s=>Number(s.id)===Number(id)):null;openModal(`${dialogHeader(current?'Edit class':'New class',current?'Rename class':'Create a class')}<form onsubmit="saveSection(event,${id||'null'})"><label class="form-field"><span>Class name</span><input id="section-name" maxlength="50" required value="${escapeHtml(current?.name||'')}"></label><div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">${current?'Save changes':'Create class'}</button></div></form>`)}
async function saveSection(event,id){event.preventDefault();const button=event.submitter;button.disabled=true;try{const section=await api(id?`/teacher/sections/${id}`:'/teacher/sections',{method:id?'PATCH':'POST',body:JSON.stringify({name:document.querySelector('#section-name').value})});state.sectionId=section.id;state.tasks=null;closeModal();showToast(id?'Class updated.':'Class created.');await loadData();location.hash='class';}catch(e){showToast(e.message,'error');button.disabled=false}}
async function deleteClass(id){const name=state.sections.find(section=>Number(section.id)===Number(id))?.name||'this class';if(!confirm(`Delete ${name}? This will remove its tasks, enrollments, and submission records. Student accounts will remain active.`))return;try{await api(`/teacher/sections/${id}`,{method:'DELETE'});state.sectionId=null;state.tasks=null;localStorage.removeItem('rizlife-section');showToast('Class deleted.');await loadData();location.hash='class';}catch(e){showToast(e.message,'error')}}
function openStudentForm(){openModal(`${dialogHeader('Add student',`Add one student to ${state.teacher.section.name}`)}<form onsubmit="createStudent(event)"><div class="invite-explainer"><span>${icons.submit}</span><div><b>Manual enrollment</b><p>Existing accounts are enrolled immediately. For a new account, RizLife prepares a secure Outlook invitation for you to send.</p></div></div><label class="form-field"><span>Full name</span><input id="student-name" maxlength="100" autocomplete="name" required></label><label class="form-field"><span>School email address</span><input id="student-email" type="email" autocomplete="email" required><small>Use the student's official APC email address.</small></label><label class="form-field"><span>Student ID <small>(optional)</small></span><input id="student-number" maxlength="100" autocomplete="off" placeholder="Example: 2026-00001"><small>Used to detect duplicate institutional records.</small></label><div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">Add student</button></div></form>`,true)}
async function createStudent(event){event.preventDefault();const popup=prepareOutlookWindow();if(!popup)return;const button=event.submitter;button.disabled=true;button.textContent='Adding student';try{const result=await api(`/teacher/sections/${state.sectionId}/students`,{method:'POST',body:JSON.stringify({name:document.querySelector('#student-name').value,email:document.querySelector('#student-email').value,studentNumber:document.querySelector('#student-number').value})});closeModal();if(result.invitationPrepared){openOutlookInvitation(result,popup);showToast('Student added. Send the prepared invitation from Outlook.')}else{popup.close();showToast('Existing student enrolled in this section.')}await loadData();if(result.invitationPrepared)showOutlookInvitation(result)}catch(e){popup.close();showToast(e.message,'error');button.disabled=false;button.textContent='Add student'}}
async function removeStudent(id){const name=state.teacher.students.find(student=>student.id===id)?.name||'this student';if(!confirm(`Remove ${name} from ${state.teacher.section.name}? The account will remain active.`))return;try{await api(`/teacher/sections/${state.sectionId}/students/${id}`,{method:'DELETE'});showToast('Student removed from the class.');await loadData();}catch(e){showToast(e.message,'error')}}
async function openStudent(id,sectionId=state.sectionId){const layer=openModal(modalSkeleton(),true);try{const result=await api(`/teacher/students/${id}?sectionId=${sectionId}`),c=counts(result.quests);layer.querySelector('.dialog').innerHTML=`${dialogHeader('Student progress',result.student.name)}<section class="compact-metrics"><div><strong>${c.verified}</strong><span>Completed</span></div><div><strong>${c.submitted}</strong><span>For review</span></div><div><strong>${c.rejected}</strong><span>Revision</span></div><div><strong>${c.pending}</strong><span>Not submitted</span></div></section>${result.quests.length?`<div class="student-quest-list">${result.quests.map(q=>`<div><b>${escapeHtml(q.title)}</b>${statusPill(q.submission?.status||'pending')}</div>`).join('')}</div>`:emptyState('No tasks assigned','Create and publish tasks from the Tasks page.')}`}catch(e){closeModal();showToast(e.message,'error')}}

function assistantMessageHtml(message){return `<div class="assistant-message ${message.role}">${message.role==='assistant'?'<span class="assistant-mini-avatar"><img src="assets/rizal-assistant.png" alt=""></span>':''}<div><span>${message.role==='assistant'?'José Rizal':escapeHtml(state.user.name.split(' ')[0])}</span><p>${escapeHtml(message.text).replace(/\n/g,'<br>')}</p></div></div>`}
function assistantWidget(student){if(!state.assistantMessages.length){const firstName=state.user.name.split(' ')[0];state.assistantMessages=[{role:'assistant',text:`Welcome, ${firstName}. I’m your Ask Rizal guide. ${student?'I can help you understand your quests, missing work, submissions, and feedback.':'I can help you check exact class progress, student task status, and your review queue.'}`}]}return `<section class="assistant-panel ${state.assistantOpen?'open':''}" id="rizal-assistant" aria-label="Ask Rizal assistant" aria-hidden="${!state.assistantOpen}"><header class="assistant-head"><div class="assistant-identity"><span class="assistant-head-avatar"><img src="assets/rizal-assistant.png" alt="Illustrated portrait of José Rizal"></span><div><b>Ask Rizal</b><span><i></i> Academic guide</span></div></div><button class="assistant-close" onclick="toggleAssistant(false)" aria-label="Close Ask Rizal">×</button></header><div class="assistant-messages" aria-live="polite">${state.assistantMessages.map(assistantMessageHtml).join('')}</div><form class="assistant-compose" onsubmit="sendAssistant(event)"><label for="assistant-input" class="sr-only">Ask Rizal a question</label><input id="assistant-input" maxlength="240" autocomplete="off" placeholder="Ask about ${student?'your quests':'your classes'}…"><button type="submit" aria-label="Send message" title="Send message">${icons.send}</button></form><p class="assistant-note">Guidance is based on your current RizLife workspace.</p></section><button class="assistant-launcher ${state.assistantOpen?'open':''}" onclick="toggleAssistant()" aria-label="${state.assistantOpen?'Close':'Open'} Ask Rizal" aria-controls="rizal-assistant" aria-expanded="${state.assistantOpen}"><span class="assistant-launcher-copy"><b>Need guidance?</b><small>Ask Rizal</small></span><span class="assistant-launcher-avatar"><img src="assets/rizal-assistant.png" alt=""></span></button>`}
function toggleAssistant(force){state.assistantOpen=typeof force==='boolean'?force:!state.assistantOpen;const panel=document.querySelector('.assistant-panel'),launcher=document.querySelector('.assistant-launcher');panel?.classList.toggle('open',state.assistantOpen);panel?.setAttribute('aria-hidden',String(!state.assistantOpen));launcher?.classList.toggle('open',state.assistantOpen);launcher?.setAttribute('aria-expanded',String(state.assistantOpen));launcher?.setAttribute('aria-label',`${state.assistantOpen?'Close':'Open'} Ask Rizal`);if(state.assistantOpen){requestAnimationFrame(()=>{const messages=document.querySelector('.assistant-messages');if(messages)messages.scrollTop=messages.scrollHeight;document.querySelector('#assistant-input')?.focus()})}}
function sendAssistant(event){event.preventDefault();const input=document.querySelector('#assistant-input'),text=input?.value.trim();if(!text)return;input.value='';sendAssistantText(text)}
async function sendAssistantText(text){if(state.assistantSending||!state.user)return;const history=state.assistantMessages.slice(-6).map(message=>({role:message.role,content:message.text}));state.assistantSending=true;state.assistantMessages.push({role:'user',text});renderAssistantMessages(true);setAssistantControlsDisabled(true);try{const result=await api('/assistant',{method:'POST',body:JSON.stringify({question:text,history,sectionId:state.sectionId})});state.assistantMessages.push({role:'assistant',text:result.answer})}catch(error){state.assistantMessages.push({role:'assistant',text:error.message||'I could not answer that question. Please try again.'})}finally{state.assistantSending=false;renderAssistantMessages(false);setAssistantControlsDisabled(false);document.querySelector('#assistant-input')?.focus()}}
function setAssistantControlsDisabled(disabled){document.querySelectorAll('.assistant-compose input,.assistant-compose button').forEach(control=>control.disabled=disabled)}
function renderAssistantMessages(typing){const container=document.querySelector('.assistant-messages');if(!container)return;container.innerHTML=state.assistantMessages.map(assistantMessageHtml).join('')+(typing?`<div class="assistant-message assistant typing"><span class="assistant-mini-avatar"><img src="assets/rizal-assistant.png" alt=""></span><div><span>José Rizal</span><p><i></i><i></i><i></i></p></div></div>`:'');container.scrollTop=container.scrollHeight}
function assistantReply(input){const text=input.toLowerCase(),student=state.user.role==='student';if(/\b(hello|hi|hey)\b|who are you/.test(text))return `Welcome, ${state.user.name.split(' ')[0]}. I’m your Ask Rizal guide. Ask me about ${student?'your progress, next quest, submissions, or feedback':'your review queue, class progress, students, or tasks'}.`;if(/sign.?out|log.?out/.test(text))return 'Use the sign-out icon beside your profile at the bottom of the navigation sidebar.';if(student){const quests=state.student?.quests||[],c=counts(quests),total=quests.length,next=quests.find(q=>q.submission?.status==='rejected')||quests.find(q=>!q.submission);if(/progress|status|how am i doing|summary/.test(text)){const pct=total?Math.round(c.verified/total*100):0;return total?`You have ${c.verified} of ${total} quests verified (${pct}%). ${c.submitted} are awaiting review, ${c.rejected} need revision, and ${c.pending} have not been submitted.`:'No quests have been published for you yet.'}if(/next|what should|priority|start/.test(text))return next?`${next.submission?.status==='rejected'?'Revise':'Start'} “${next.title}” next. ${next.submission?.status==='rejected'?'Open the quest to read your teacher’s feedback before resubmitting.':'Open Rizal Quests to review its instructions and evidence requirement.'}`:(c.submitted?'Your submitted work is awaiting teacher review. You’re caught up for now!':total?'All published quests are verified. Excellent work.':'Your teacher has not published a quest yet.');if(/submit|upload|evidence|send work/.test(text))return 'Open Rizal Quests, choose a quest, then select Link, Text response, or Upload image. Add the required evidence and press “Submit for review.”';if(/feedback|revision|rejected|returned/.test(text))return c.rejected?`You have ${c.rejected} quest${c.rejected===1?'':'s'} needing revision. Open My Submissions to read the feedback, then open the quest and resubmit your improved evidence.`:'You currently have no quests returned for revision.';if(/submission|review|waiting/.test(text))return c.submitted?`${c.submitted} submission${c.submitted===1?' is':'s are'} waiting for teacher review. You can track decisions from My Submissions.`:'You have no submissions waiting for review.';if(/quest|task|activity/.test(text))return `You currently have ${total} published quest${total===1?'':'s'}. Open Rizal Quests to see instructions, requirements, and status filters.`;return 'I can guide you through your progress, next quest, submissions, teacher feedback, or evidence requirements. Choose a suggested question below.'}const d=state.teacher||{students:[],queue:[],taskCount:0},students=d.students||[],queue=d.queue||[];if(/attention|priority|review|queue|pending/.test(text))return queue.length?`${queue.length} submission${queue.length===1?' needs':'s need'} review. ${queue[0]?.student_name?`Begin with ${queue[0].student_name}’s “${queue[0].title}” submission because the queue is ordered oldest first.`:'Open Reviews to begin.'}`:'Your review queue is clear. No student submissions need attention right now.';if(/progress|summary|class|how.*doing/.test(text)){const verified=students.reduce((sum,s)=>sum+Number(s.verified||0),0),possible=students.length*Number(d.taskCount||0),pct=possible?Math.round(verified/possible*100):0;return state.sectionId?`${d.section?.name||'This class'} has ${students.length} student${students.length===1?'':'s'} and ${d.taskCount||0} active task${d.taskCount===1?'':'s'}. Overall verified progress is ${pct}%, with ${queue.length} submission${queue.length===1?'':'s'} awaiting review.`:'Create or select a class to see its progress summary.'}if(/create.*task|new task|publish|quest/.test(text))return 'Open Tasks and choose “Create task.” Add a clear title, student instructions, and the evidence requirement. Saving publishes it to the selected class.';if(/student|invite|enroll|class list/.test(text))return `The selected class has ${students.length} enrolled student${students.length===1?'':'s'}. Open Class to invite students, resend pending invitations, or inspect individual progress.`;if(/feedback|approve|return/.test(text))return 'Open Reviews and select a submission. Add actionable feedback, then choose “Approve submission” or “Return for revision.” Feedback is required when returning work.';return 'I can summarize class progress, identify submissions needing review, explain task creation, or guide you through student invitations. Choose a suggested question below.'}

function progressCelebration(percent){if(percent>=100)return ['Outstanding work!','Every class quest is verified.','complete'];if(percent>=75)return ['Almost there!','The class is close to the finish line.','active'];if(percent>=50)return ['Strong progress!','More than half the journey is complete.','active'];if(percent>=25)return ['Good job!','The class is building real momentum.','active'];if(percent>0)return ['Great start!','Every verified quest moves the class forward.','active'];return ['Ready to begin','The first verified quest will start the celebration.','idle']}
function enhanceTeacherProgress(){const progress=app.querySelector('.teacher-brief .brief-progress');if(!progress||progress.querySelector('.progress-cheer'))return;const percent=Math.max(0,Math.min(100,Number.parseInt(progress.querySelector('strong')?.textContent,10)||0)),[title,note,band]=progressCelebration(percent),cheer=document.createElement('div');cheer.className='progress-cheer';cheer.innerHTML='<span aria-hidden="true">✦</span><div><b></b><small></small></div>';cheer.querySelector('b').textContent=title;cheer.querySelector('small').textContent=note;progress.append(cheer);progress.closest('.teacher-brief')?.setAttribute('data-progress-band',band)}
function studentMotivation(percent){if(percent>=100)return ['Journey completed','You finished every published quest. Be proud of the work you did.','complete'];if(percent>=67)return ['The finish line is close','Stay focused—your next completed quest brings you closer.','active'];if(percent>=34)return ['Your momentum is growing','You are building a meaningful learning streak.','active'];if(percent>0)return ['Off to a good start','One quest down. Rizal would probably give a very serious nod.','active'];return ['The adventure is still in the prologue','No quests done yet—your plot twist can start with Quest 01.','idle']}
function enhanceStudentProgress(){const progress=app.querySelector('.journey-progress'),hero=app.querySelector('.journey-hero'),copy=hero?.querySelector('.journey-hero-copy'),portrait=hero?.querySelector('.journey-portrait');if(!progress||!hero||!copy||copy.querySelector('.journey-encouragement'))return;const percent=Math.max(0,Math.min(100,Number.parseInt(progress.querySelector('.journey-progress-bar strong')?.textContent,10)||0)),[title,note,band]=studentMotivation(percent),message=document.createElement('div'),quote=document.createElement('blockquote');message.className='journey-encouragement';message.innerHTML='<div><b></b><small></small></div>';message.querySelector('b').textContent=title;message.querySelector('small').textContent=note;copy.append(message);quote.className='journey-rizal-quote';quote.innerHTML='<p>“The example could encourage others who only fear to start.”</p><cite>— José Rizal, <a href="https://www.goodreads.com/work/quotes/407434" target="_blank" rel="noopener noreferrer">Noli Me Tángere</a></cite>';portrait?.append(quote);hero.setAttribute('data-progress-band',band);progress.setAttribute('data-progress-band',band)}
function enhanceProgressMoments(){enhanceTeacherProgress();enhanceStudentProgress()}
const progressObserver=new MutationObserver(enhanceProgressMoments);progressObserver.observe(app,{childList:true,subtree:true});

async function start(){const query=new URLSearchParams(location.search),confirmationUrl=query.get('confirmation_url'),hash=new URLSearchParams(location.hash.slice(1)),invitePath=location.pathname==='/accept-invite';if(confirmationUrl)return invitationLandingPage(confirmationUrl);if(hash.get('type')==='invite'&&hash.get('access_token')&&hash.get('refresh_token'))return acceptInvitation(hash);if(invitePath)return errorScreen('This invitation link is incomplete, invalid, or has expired. Open the latest invitation sent by your teacher.');try{state.user=(await api('/me')).user;await loadData();}catch{loginPage()}}
start();
